(window.QBANK = window.QBANK || []).push(
  {"id": "prac-sc-1", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. The dimensional formula of b is the same as that of:", "options": ["P", "V", "PV²", "RT"], "answer": 1, "hint": "Only like quantities can be subtracted.", "solution": "$V-b$ ⇒ b has the dimensions of V.", "source": "Sri Chaitanya · Total Physics Important Questions · Q1", "kind": "practice"},
  {"id": "prac-sc-2", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. The dimensional formula of a is the same as that of:", "options": ["V²", "P", "PV²", "RT"], "answer": 2, "hint": "$a/V^2$ adds to P.", "solution": "$[a]=[P][V^2]$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q2", "kind": "practice"},
  {"id": "prac-sc-3", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. Which does NOT have the same dimensions as RT?", "options": ["PV", "Pb", "a/V²", "ab/V²"], "answer": 2, "hint": "RT has dimensions of PV (energy per mole).", "solution": "$a/V^2$ has dimensions of P only. $Pb$ and $ab/V^2=PV^2\\cdot V/V^2$ both equal PV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q3", "kind": "practice"},
  {"id": "prac-sc-5", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "Two vectors vary with time as $\\vec a=3t\\hat i+4t^2\\hat j$ and $\\vec b=(6t+3)\\hat i+(7\\sin t)\\hat j$. The rate of change of $\\vec a\\cdot\\vec b$ at t = 0 is:", "options": ["36", "9", "28", "45"], "answer": 1, "hint": "Differentiate $3t(6t+3)+28t^2\\sin t$.", "solution": "$\\frac{d}{dt}=36t+9+(\\ldots)t$ terms ⇒ 9 at t = 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q5", "kind": "practice"},
  {"id": "prac-sc-6", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "Two vectors vary with time as $\\vec a=3t\\hat i+4t^2\\hat j$ and $\\vec b=(6t+3)\\hat i+(7\\sin t)\\hat j$. The rate of change of $\\vec a\\cdot(\\vec a\\times\\vec b)$ at t = 0 is:", "options": ["72", "36", "48", "zero"], "answer": 3, "hint": "$\\vec a\\times\\vec b$ is perpendicular to $\\vec a$.", "solution": "$\\vec a\\cdot(\\vec a\\times\\vec b)=0$ at all times, so its rate is zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q6", "kind": "practice"},
  {"id": "prac-sc-7", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. Its speed after 5 m (m/s) is:", "options": ["5", "10", "20", "30"], "answer": 1, "hint": "Work = $\\int F\\,dx$ = change in KE.", "solution": "$W=\\int_0^5(10+4x)dx=100$ J $=\\frac12(2)v^2$ ⇒ v = 10 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q7", "kind": "practice"},
  {"id": "prac-sc-8", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 1, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. The force at that moment (N) is:", "options": ["20", "5", "30", "40"], "answer": 2, "hint": "Put x = 5.", "solution": "$F=10+20=30$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q8", "kind": "practice"},
  {"id": "prac-sc-9", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. The instantaneous power at that moment is:", "options": ["200 W", "300 W", "400 W", "500 W"], "answer": 1, "hint": "P = Fv.", "solution": "$30\\times10=300$ W.", "source": "Sri Chaitanya · Total Physics Important Questions · Q9", "kind": "practice"},
  {"id": "prac-sc-10", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The mean angular velocity from t = 0 until the body stops is:", "options": ["2 rad/s", "4 rad/s", "3 rad/s", "12 rad/s"], "answer": 1, "hint": "It stops when $\\omega=k-3bt^2=0$.", "solution": "t = 1 s; $\\langle\\omega\\rangle=\\frac{\\theta(1)}{1}=6-2=4$ rad/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q10", "kind": "practice"},
  {"id": "prac-sc-11", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The magnitude of the mean angular acceleration from t = 0 until the body stops is:", "options": ["6 rad/s²", "24 rad/s²", "18 rad/s²", "12 rad/s²"], "answer": 0, "hint": "$\\langle\\alpha\\rangle=\\Delta\\omega/\\Delta t$.", "solution": "ω goes from 6 to 0 in 1 s ⇒ 6 rad/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q11", "kind": "practice"},
  {"id": "prac-sc-12", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 2, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The magnitude of the angular acceleration at the moment the body stops is:", "options": ["18 rad/s²", "24 rad/s²", "6 rad/s²", "12 rad/s²"], "answer": 3, "hint": "$\\alpha=-6bt$.", "solution": "At t = 1 s: |α| = 12 rad/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q12", "kind": "practice"},
  {"id": "prac-sc-13", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The constant C is:", "options": ["$v_0/2$", "$v_0$", "$v_0\\frac{M}{m}$", "$v_0\\frac{m}{M}$"], "answer": 1, "hint": "Put t = 0.", "solution": "$v(0)=C=v_0$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q13", "kind": "practice"},
  {"id": "prac-sc-14", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The acceleration of the boat as a function of time is:", "options": ["$\\frac{kv_0}{M}e^{-kt/M}\\hat i$", "$\\frac{kv_0}{M}e^{-kt/M}(-\\hat i)^{-1}$", "$-\\frac{kv_0}{M}e^{-kt/M}\\hat i$", "$-\\frac{kv_0}{M}e^{kt/M}\\hat i$"], "answer": 2, "hint": "Differentiate $v_0e^{-kt/M}$.", "solution": "$a=-\\frac{kv_0}{M}e^{-kt/M}\\hat i$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q14", "kind": "practice"},
  {"id": "prac-sc-15", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 4, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The horizontal acceleration of the ball in the ground frame ($a_x$) and in the boat frame ($a_{x'}$) are respectively:", "options": ["$0$; $\\frac{kv_0}{M}e^{-kt/M}$", "$0$; $-\\frac{kv_0}{M}e^{-kt/M}$", "$a_x=a_{x'}=-\\frac{kv_0}{M}e^{-kt/M}$", "$0$; $-\\frac{kv_0}{M}e^{kt/M}$"], "answer": 0, "hint": "No horizontal force on the ball; the boat decelerates.", "solution": "Ground: $a_x=0$. Boat frame: $a_{x'}=0-a_{boat}=+\\frac{kv_0}{M}e^{-kt/M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q15", "kind": "practice"},
  {"id": "prac-sc-16", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average acceleration over the whole motion is:", "options": ["4 m/s²", "zero", "8 m/s²", "−4 m/s²"], "answer": 1, "hint": "Compare initial and final velocity.", "solution": "It starts and ends at rest ⇒ zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q16", "kind": "practice"},
  {"id": "prac-sc-17", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average speed over the whole motion is:", "options": ["8 m/s", "zero", "4 m/s", "16 m/s"], "answer": 0, "hint": "Max speed 16 m/s; add the two areas under v–t.", "solution": "Distance $=32+64=96$ m in 12 s ⇒ 8 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q17", "kind": "practice"},
  {"id": "prac-sc-18", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average velocity over the whole motion is:", "options": ["zero", "8 m/s", "2 m/s", "4 m/s"], "answer": 1, "hint": "The motion is in one direction.", "solution": "$96/12=8$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q18", "kind": "practice"},
  {"id": "prac-sc-19", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The equation of the trajectory is:", "options": ["$y=x^2\\frac{b}{a^2}$", "$y=-x\\frac{b}{a^2}$", "$y=-x^2\\frac{b}{a^2}$", "$y=-x^2\\frac{b}{a}$"], "answer": 2, "hint": "Eliminate t using $x=at$.", "solution": "$y=-b\\left(\\frac xa\\right)^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q19", "kind": "practice"},
  {"id": "prac-sc-20", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The velocity as a function of time is:", "options": ["$-a\\hat i-2bt\\hat j$", "$a\\hat i-2b\\hat j$", "$a\\hat i-2bt\\hat j$", "$a\\hat i+2bt\\hat j$"], "answer": 2, "hint": "Differentiate $\\vec r$.", "solution": "$\\vec v=a\\hat i-2bt\\hat j$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q20", "kind": "practice"},
  {"id": "prac-sc-21", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The acceleration of the point is:", "options": ["$2a\\hat j$", "$2b^2\\hat j$", "$2b\\hat j$", "$-2b\\hat j$"], "answer": 3, "hint": "Differentiate $\\vec v$.", "solution": "$\\vec a=-2b\\hat j$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q21", "kind": "practice"},
  {"id": "prac-sc-22", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at A is:", "options": ["100 N", "150 N", "200 N", "50 N"], "answer": 0, "hint": "Whole system (10 kg) accelerates at $a=\\frac{200-100}{10}$.", "solution": "$a=10$ m/s². $T_A=(3+2)(g+a)=100$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q22", "kind": "practice"},
  {"id": "prac-sc-23", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at B is:", "options": ["60 N", "40 N", "70 N", "100 N"], "answer": 2, "hint": "Below B hang 1.5 kg of rope + 2 kg.", "solution": "$T_B=3.5\\times20=70$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q23", "kind": "practice"},
  {"id": "prac-sc-24", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at C is:", "options": ["10 N", "30 N", "20 N", "40 N"], "answer": 3, "hint": "Only the 2 kg block hangs below C.", "solution": "$T_C=2\\times20=40$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q24", "kind": "practice"},
  {"id": "prac-sc-25", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The force exerted by the 3 kg block on the 2 kg block is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 0, "hint": "$a=\\frac{(10-5)g}{15}=\\frac g3$; the pan side moves up.", "solution": "$N=2\\left(g+\\frac g3\\right)=\\frac{8g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q25", "kind": "practice"},
  {"id": "prac-sc-26", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The force exerted by the 3 kg block on the pan is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 2, "hint": "The pan must accelerate both blocks (5 kg) upward.", "solution": "$5\\left(g+\\frac g3\\right)=\\frac{20g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q26", "kind": "practice"},
  {"id": "prac-sc-27", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The tension in the string is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 2, "hint": "The pan is massless.", "solution": "$T$ = force needed on the 5 kg load $=\\frac{20g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q27", "kind": "practice"},
  {"id": "prac-sc-28", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) The coefficient of static friction is approximately:", "options": ["0.25", "2.5", "0.40", "4.0"], "answer": 2, "hint": "Limiting friction = 400 N.", "solution": "$\\mu_s=\\frac{400}{1000}=0.40$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q28", "kind": "practice"},
  {"id": "prac-sc-29", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) When the push was 50 N the crate did not move, because:", "options": ["the push was weaker than the friction on the crate", "the push equalled the gravitational force", "the push had the same strength as the friction on the crate", "the push was stronger than the friction"], "answer": 2, "hint": "Static friction adjusts itself.", "solution": "At rest, static friction exactly balances the push: 50 N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q29", "kind": "practice"},
  {"id": "prac-sc-30", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) The coefficient of kinetic friction is approximately:", "options": ["0.30", "0.20", "0.40", "0.50"], "answer": 1, "hint": "From 500 N: $s=\\frac12at^2$ ⇒ a.", "solution": "$a=3$ m/s² ⇒ $500-f=300$ ⇒ $f=200$ N ⇒ $\\mu_k=0.20$ (600 N gives the same).", "source": "Sri Chaitanya · Total Physics Important Questions · Q30", "kind": "practice"},
  {"id": "prac-sc-31", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. The maximum value of M/m for which the system stays at rest is:", "options": ["$\\frac{\\mu}{\\cos\\theta+\\mu\\sin\\theta}$", "$\\frac{\\mu}{\\cos\\theta-\\mu\\sin\\theta}$", "$\\frac{\\mu}{\\sin\\theta+\\mu\\cos\\theta}$", "$\\frac{\\mu}{\\sin\\theta-\\mu\\cos\\theta}$"], "answer": 3, "hint": "At the limit, M's weight component = both frictions.", "solution": "$Mg\\sin\\theta=\\mu Mg\\cos\\theta+\\mu mg$ ⇒ $\\frac Mm=\\frac{\\mu}{\\sin\\theta-\\mu\\cos\\theta}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q31", "kind": "practice"},
  {"id": "prac-sc-32", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. When $\\tan\\theta<\\mu$:", "options": ["the system will not slide for any value of M/m", "M will move upwards", "M will lose contact with the incline", "both bodies move with constant velocity"], "answer": 0, "hint": "Even without m, would M slide?", "solution": "$\\sin\\theta<\\mu\\cos\\theta$ ⇒ friction alone can hold M, so it never slides.", "source": "Sri Chaitanya · Total Physics Important Questions · Q32", "kind": "practice"},
  {"id": "prac-sc-33", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. If M is large enough for the system to slide, the acceleration of M is:", "options": ["$\\frac{Mg\\sin\\theta+\\mu g(m+M\\cos\\theta)}{m+M}$", "$\\frac{Mg\\cos\\theta+\\mu g(m+M\\sin\\theta)}{m+M}$", "$\\frac{Mg\\sin\\theta-\\mu g(m+M\\cos\\theta)}{m+M}$", "$\\frac{Mg\\cos\\theta-\\mu g(m+M\\sin\\theta)}{m+M}$"], "answer": 2, "hint": "Net driving force / total mass.", "solution": "$a=\\frac{Mg\\sin\\theta-\\mu Mg\\cos\\theta-\\mu mg}{m+M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q33", "kind": "practice"},
  {"id": "prac-sc-34", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the upper block. Its acceleration is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 2, "hint": "Check whether they move together (max friction = 4 N).", "solution": "Together would need 8 N on the lower block > 4 N ⇒ slip. $a_{up}=\\frac{12-4}{2}=4$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q34", "kind": "practice"},
  {"id": "prac-sc-35", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the upper block. The acceleration of the lower block is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 1, "hint": "Only kinetic friction (4 N) drives it.", "solution": "$\\frac44=1$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q35", "kind": "practice"},
  {"id": "prac-sc-36", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the lower block. The acceleration of the upper block is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 0, "hint": "Together: $a=12/6$; is friction enough?", "solution": "$a=2$ needs 4 N on the upper block = the maximum, so they just move together at 2 m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q36", "kind": "practice"},
  {"id": "prac-sc-37", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Three smooth pulleys are connected by a light string as shown; mass m hangs from pulley P₃. The strings are vertical. If all the pulleys are massless, the tension in the string over the pulleys is:", "img": "figures/prac-sc-p13.png", "imgAlt": "Pulley P₁ hangs in a string loop from the ceiling; the string passes over fixed P₂ and under P₃, which carries mass m", "options": ["mg", "zero", "2mg", "mg/2"], "answer": 1, "hint": "Look at the free massless pulley P₁: what balances it?", "solution": "P₁ is massless and hangs only on the string, so the net force on it must vanish ⇒ 2T = 0 ⇒ T = 0 (m falls freely).", "source": "Sri Chaitanya · Total Physics Important Questions · Q37", "kind": "practice"},
  {"id": "prac-sc-39", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Three smooth pulleys are connected by a light string as shown; mass m hangs from pulley P₃. The strings are vertical. The tension in the string over the pulleys will be non-zero when:", "options": ["mass of P₁ is zero", "mass of P₂ is zero", "mass of P₂ is non-zero", "mass of P₁ is non-zero"], "answer": 3, "hint": "Which pulley's weight must the string support?", "solution": "Only a massive P₁ needs the string to hold it up; P₂ is fixed.", "source": "Sri Chaitanya · Total Physics Important Questions · Q39", "kind": "practice"},
  {"id": "prac-sc-40", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes up with acceleration 1.2 m/s² is:", "options": ["0.60 N", "0.56 N", "0.75 N", "0.45 N"], "answer": 1, "hint": "$T=m(g+a)$.", "solution": "$0.05\\times11.2=0.56$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q40", "kind": "practice"},
  {"id": "prac-sc-41", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes up at uniform velocity is:", "options": ["0.5 N", "0.43 N", "0.52 N", "0.75 N"], "answer": 0, "hint": "No acceleration.", "solution": "$T=mg=0.5$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q41", "kind": "practice"},
  {"id": "prac-sc-42", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes down with deceleration 1.2 m/s² is:", "options": ["0.49 N", "0.43 N", "0.56 N", "0.75 N"], "answer": 2, "hint": "Moving down and slowing ⇒ acceleration is upward.", "solution": "$T=m(g+a)=0.56$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q42", "kind": "practice"},
  {"id": "prac-sc-43", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The compression of the first spring (k₁) is:", "options": ["1.3 m", "−0.5 m", "0.5 m", "0.9 m"], "answer": 1, "hint": "Find T from m₂: $T=80-35$.", "solution": "$T=45$ N. For m₁: $45=20+F_1$ ⇒ spring pulls m₁ down with 25 N ⇒ extension 0.5 m, i.e. compression −0.5 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q43", "kind": "practice"},
  {"id": "prac-sc-44", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The acceleration of m₁ just after spring k₁ is cut is:", "options": ["zero", "2.5 m/s²", "3 m/s²", "none"], "answer": 1, "hint": "The string system now: $m_2g-F_2-m_1g$ over 10 kg.", "solution": "$a=\\frac{80-35-20}{10}=2.5$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q44", "kind": "practice"},
  {"id": "prac-sc-45", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The acceleration of m₁ just after the string is cut is:", "options": ["20 m/s²", "22.5 m/s²", "25 m/s²", "25.5 m/s²"], "answer": 1, "hint": "Remaining forces on m₁: weight and the stretched spring, both downward.", "solution": "$\\frac{20+25}{2}=22.5$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q45", "kind": "practice"},
  {"id": "prac-sc-46", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A smooth track has an inclined straight part of length ℓ (angle θ) that joins smoothly with a circular part of radius R, as shown. A particle is projected up the incline from its bottom. The minimum projection speed $v_0$ for the particle to reach the top of the track is:", "img": "figures/prac-sc-p16.png", "imgAlt": "An incline of length ℓ at angle θ joins a circle of radius R at its upper end", "options": ["$\\sqrt{2g(\\ell\\sin\\theta+R\\cos\\theta)}$", "$\\sqrt{2gR(1-\\cos\\theta)}$", "$\\sqrt{2g\\ell\\sin\\theta}$", "$\\sqrt{2g[R(1-\\cos\\theta)+\\ell\\sin\\theta]}$"], "answer": 3, "hint": "Total rise = incline + circular part above the joint.", "solution": "Height $=\\ell\\sin\\theta+R(1-\\cos\\theta)$ ⇒ $v_0=\\sqrt{2gh}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q46", "kind": "practice"},
  {"id": "prac-sc-48", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 4, "q": "A smooth track has an inclined straight part of length ℓ (angle θ) that joins smoothly with a circular part of radius R, as shown. A particle is projected up the incline from its bottom. If the particle reaches the top of the circular part with a very small speed, it leaves the track when the radius through it makes an angle with the vertical of:", "img": "figures/prac-sc-p16.png", "imgAlt": "An incline of length ℓ at angle θ joins a circle of radius R at its upper end", "options": ["$\\cos^{-1}\\frac13$", "$\\cos^{-1}\\frac23$", "$\\cos^{-1}\\frac35$", "$\\cos^{-1}\\frac45$"], "answer": 1, "hint": "On a convex surface: $mg\\cos\\phi=\\frac{mv^2}{R}$ with $v^2=2gR(1-\\cos\\phi)$.", "solution": "$\\cos\\phi=2(1-\\cos\\phi)$ ⇒ $\\cos\\phi=\\frac23$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q48", "kind": "practice"},
  {"id": "prac-sc-49", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 1, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the ladder on the boy as he climbs is:", "options": ["600 J", "1600 J", "zero", "800 J"], "answer": 2, "hint": "Does the point where the force acts move?", "solution": "The ladder's force acts at a stationary contact point ⇒ zero work.", "source": "Sri Chaitanya · Total Physics Important Questions · Q49", "kind": "practice"},
  {"id": "prac-sc-50", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the slide on the boy as he comes down is:", "options": ["1600 J", "−600 J", "zero", "500 J"], "answer": 1, "hint": "Normal force does no work; friction acts over 10 m.", "solution": "$-0.3\\times200\\times10=-600$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q50", "kind": "practice"},
  {"id": "prac-sc-51", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the forces inside the boy's body (while climbing) is:", "options": ["zero", "−600 J", "800 J", "1600 J"], "answer": 3, "hint": "His muscles supply the potential energy gained.", "solution": "$mgh=200\\times8=1600$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q51", "kind": "practice"},
  {"id": "prac-sc-53", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A 2 kg particle on a string moves in a vertical circle of radius 2 m. (g = 10 m/s²) It is given 12 m/s at the lowest point. The tension at the highest point is:", "options": ["100 N", "44 N", "144 N", "264 N"], "answer": 1, "hint": "$v_{top}^2=u^2-4gR$.", "solution": "$v^2=144-80=64$ ⇒ $T=\\frac{2\\times64}{2}-20=44$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q53", "kind": "practice"},
  {"id": "prac-sc-54", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle on a string moves in a vertical circle of radius 2 m. (g = 10 m/s²) It is given 10 m/s at the lowest point. Its speed when the string makes 60° with the downward vertical is:", "options": ["$2\\sqrt5$ m/s", "$4\\sqrt5$ m/s", "$5\\sqrt2$ m/s", "5 m/s"], "answer": 1, "hint": "Rise $h=R(1-\\cos60°)=1$ m.", "solution": "$v^2=100-20=80$ ⇒ $4\\sqrt5$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q54", "kind": "practice"},
  {"id": "prac-sc-55", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. The motion of the ball is:", "options": ["circular motion with variable speed", "circular motion with constant speed", "circular motion with constant angular acceleration", "none of these"], "answer": 0, "hint": "Gravity has a tangential component.", "solution": "Speed changes with height; the tangential acceleration $g\\sin\\theta$ also varies.", "source": "Sri Chaitanya · Total Physics Important Questions · Q55", "kind": "practice"},
  {"id": "prac-sc-56", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. At the highest point, the tangential acceleration is:", "options": ["g", "0", "5g", "16g"], "answer": 1, "hint": "At the top, gravity is radial.", "solution": "Gravity points to the centre ⇒ tangential acceleration 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q56", "kind": "practice"},
  {"id": "prac-sc-57", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. The minimum tension in the string during the motion is:", "options": ["zero", "mg", "15mg", "10mg"], "answer": 2, "hint": "Minimum at the top: $v^2=20gl-4gl$.", "solution": "$T=\\frac{m(16gl)}{l}-mg=15mg$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q57", "kind": "practice"},
  {"id": "prac-sc-58", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along OAC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 0, "hint": "On OA, y = 0 so F = 0.", "solution": "A→C (x = 1): $\\int_0^4 y\\,dy=8$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q58", "kind": "practice"},
  {"id": "prac-sc-59", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along OBC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 1, "hint": "On OB, x = 0 so F = 0.", "solution": "B→C (y = 4): $\\int_0^1 4x\\,dx=2$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q59", "kind": "practice"},
  {"id": "prac-sc-60", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along ODC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 2, "hint": "Use $y=4x^2$, $dy=8x\\,dx$.", "solution": "$\\int_0^1(4x^3+32x^5)dx=1+\\frac{16}{3}=\\frac{19}{3}$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q60", "kind": "practice"},
  {"id": "prac-sc-61", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 2, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The speed of the disc at B is:", "options": ["$\\sqrt{2g\\ell\\sin\\theta}$", "$\\sqrt{\\frac{2g\\ell}{3}\\sin\\theta}$", "$\\sqrt{2g\\ell}$", "$\\sqrt{\\frac{4g\\ell}{3}\\sin\\theta}$"], "answer": 3, "hint": "KE of a rolling disc = $\\frac34MV^2$.", "solution": "$\\frac34MV^2=Mg\\ell\\sin\\theta$ ⇒ $V^2=\\frac43g\\ell\\sin\\theta$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q61", "kind": "practice"},
  {"id": "prac-sc-62", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The kinetic energy of the disc at B is:", "options": ["$Mg\\ell/2$", "$\\frac{3M}{4}V^2$", "$Mg\\ell\\sin\\theta$", "$\\frac23Mg\\ell\\sin\\theta$"], "answer": 1, "hint": "Translational + rotational ($I=\\frac12MR^2$).", "solution": "$\\frac12MV^2+\\frac14MV^2=\\frac34MV^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q62", "kind": "practice"},
  {"id": "prac-sc-63", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The work done by friction $W_f$ is:", "options": ["zero", "$-Mg\\ell\\sin\\theta$", "$\\frac34MV^2-Mg\\ell\\sin\\theta$", "both (A) and (C) are correct"], "answer": 3, "hint": "Rolling without slipping: the contact point doesn't slide.", "solution": "Static friction does no work, and by the work–energy theorem $\\frac34MV^2-Mg\\ell\\sin\\theta=0$ too.", "source": "Sri Chaitanya · Total Physics Important Questions · Q63", "kind": "practice"},
  {"id": "prac-sc-64", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 1, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The velocity of the combined 2 kg mass just after the collision is:", "options": ["3 m/s", "6 m/s", "1 m/s", "1.5 m/s"], "answer": 0, "hint": "Momentum conserved in the brief collision (trolley not involved).", "solution": "$1\\times6=2v$ ⇒ 3 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q64", "kind": "practice"},
  {"id": "prac-sc-65", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The trolley's velocity at maximum deflection of the ball is:", "options": ["3 m/s", "6 m/s", "1 m/s", "1.5 m/s"], "answer": 2, "hint": "At maximum deflection ball and trolley share one velocity.", "solution": "$6=6v$ ⇒ 1 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q65", "kind": "practice"},
  {"id": "prac-sc-66", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 4, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The maximum inclination of the thread with the vertical is:", "options": ["30°", "37°", "45°", "53°"], "answer": 1, "hint": "KE lost = $2mgh$.", "solution": "$9-3=6$ J $=20h$ ⇒ h = 0.3 m ⇒ $\\cos\\phi=\\frac{1.2}{1.5}=0.8$ ⇒ 37°.", "source": "Sri Chaitanya · Total Physics Important Questions · Q66", "kind": "practice"},
  {"id": "prac-sc-67", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A smooth 8 kg wedge (height 6 m, incline angle 37° at its base) rests on a smooth floor. A 2 kg block is released at the top of the incline. The displacement of the wedge when the block reaches the bottom is:", "options": ["1.6 m", "2 m", "1.5 m", "1.2 m"], "answer": 0, "hint": "Horizontal COM stays fixed; the incline's base is $6/\\tan37°=8$ m.", "solution": "$2(8-x)=8x$ ⇒ x = 1.6 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q67", "kind": "practice"},
  {"id": "prac-sc-68", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A smooth 8 kg wedge (height 6 m, incline angle 37° at its base) rests on a smooth floor. A 2 kg block is released at the top of the incline. Seen from the ground, the block moves:", "options": ["at 37° below the horizontal", "at more than 37° below the horizontal", "at 90° to the horizontal", "horizontally"], "answer": 1, "hint": "The wedge recoils, reducing the block's horizontal velocity.", "solution": "Its vertical velocity is unchanged while its horizontal one shrinks ⇒ steeper than 37°.", "source": "Sri Chaitanya · Total Physics Important Questions · Q68", "kind": "practice"},
  {"id": "prac-sc-70", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. The boy's displacement relative to the ground when he reaches B is:", "options": ["20 m", "16 m", "15 m", "12 m"], "answer": 1, "hint": "No external horizontal force: $25x_b=100x_p$, $x_b+x_p=20$.", "solution": "$x_p=4$ m ⇒ boy moves 16 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q70", "kind": "practice"},
  {"id": "prac-sc-71", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. The velocity of the plank is:", "options": ["10 cm/s", "12.5 cm/s", "25 cm/s", "50 cm/s"], "answer": 0, "hint": "$25v_b=100v_p$ and $v_b+v_p=0.5$.", "solution": "$v_p=0.1$ m/s = 10 cm/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q71", "kind": "practice"},
  {"id": "prac-sc-72", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. Choose the INCORRECT statement:", "options": ["Momentum of the whole system is conserved", "Momentum of the boy can't stay conserved because of friction", "Momentum of the plank can't stay conserved because of friction", "The centre of mass of the whole system moves along +x"], "answer": 3, "hint": "No external horizontal force acts on boy + plank.", "solution": "The system's COM stays at rest, so (D) is incorrect.", "source": "Sri Chaitanya · Total Physics Important Questions · Q72", "kind": "practice"},
  {"id": "prac-sc-73", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. Choose the INCORRECT statement:", "options": ["Friction does negative translational work", "Friction does positive rotational work", "The net work done by friction is zero", "Friction converts translational KE into rotational KE"], "answer": 2, "hint": "Kinetic friction acts while the ring slips.", "solution": "Energy is dissipated during slipping, so the net work by friction is negative, not zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q73", "kind": "practice"},
  {"id": "prac-sc-74", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. The velocity of the centre of the ring when it starts pure rolling is:", "options": ["$v_0/4$", "$v_0/2$", "$v_0/3$", "$2v_0/3$"], "answer": 1, "hint": "Angular momentum about the contact point is conserved.", "solution": "$Mv_0R=Mv R+MR^2\\frac vR$ ⇒ $v=\\frac{v_0}{2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q74", "kind": "practice"},
  {"id": "prac-sc-75", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. The distance moved by its centre on the rough surface before pure rolling starts is:", "options": ["$\\frac{3v_0^2}{8\\mu g}$", "$\\frac{2v_0^2}{8\\mu g}$", "$\\frac{v_0^2}{\\mu g}$", "$\\frac{5v_0^2}{8\\mu g}$"], "answer": 0, "hint": "Rolling starts at $v=v_0/2$ with deceleration μg.", "solution": "$t=\\frac{v_0}{2\\mu g}$, $s=\\frac{v_0^2-v_0^2/4}{2\\mu g}=\\frac{3v_0^2}{8\\mu g}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q75", "kind": "practice"},
  {"id": "prac-sc-76", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Both blocks have the same velocity when the elongation is:", "options": ["$\\frac{m_2F}{2K(m_1+m_2)}$", "$\\frac{m_2F}{K(m_1+m_2)}$", "$\\frac{2m_2F}{K(m_1+m_2)}$", "$\\frac{4m_2F}{K(m_1+m_2)}$"], "answer": 2, "hint": "Equal velocities ⇔ relative velocity zero ⇔ maximum elongation.", "solution": "In the COM frame the reduced system oscillates about $\\frac{m_2F}{K(m_1+m_2)}$, so the maximum is twice that.", "source": "Sri Chaitanya · Total Physics Important Questions · Q76", "kind": "practice"},
  {"id": "prac-sc-77", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Both blocks have the same acceleration when the elongation is:", "options": ["$\\frac{m_2F}{2K(m_1+m_2)}$", "$\\frac{m_2F}{K(m_1+m_2)}$", "$\\frac{2m_2F}{K(m_1+m_2)}$", "$\\frac{4m_2F}{K(m_1+m_2)}$"], "answer": 1, "hint": "Both then accelerate at $\\frac{F}{m_1+m_2}$.", "solution": "For $m_2$: $Kx=m_2\\frac{F}{m_1+m_2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q77", "kind": "practice"},
  {"id": "prac-sc-78", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Select the correct alternative:", "options": ["The velocity of the COM equals that of $m_1$ and $m_2$ when the elongation is $x_0$", "It equals theirs when the elongation is $x_0/2$", "It can never equal theirs", "The COM velocity can become zero during the motion"], "answer": 0, "hint": "When do both blocks share one velocity?", "solution": "At maximum elongation both move together, so they also move with the COM.", "source": "Sri Chaitanya · Total Physics Important Questions · Q78", "kind": "practice"},
  {"id": "prac-sc-79", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. In case (a), the COM velocity and angular velocity are:", "options": ["$\\frac{\\Delta p}{M}$; $\\frac{\\Delta p}{2Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{Ml}$", "$\\frac{2\\Delta p}{M}$; $\\frac{\\Delta p}{4Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{2Ml}$"], "answer": 1, "hint": "Angular impulse about the COM = $\\Delta p\\cdot\\frac l2$; $I=\\frac{Ml^2}{2}$.", "solution": "$v=\\frac{\\Delta p}{2M}$, $\\omega=\\frac{\\Delta p\\,l/2}{Ml^2/2}=\\frac{\\Delta p}{Ml}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q79", "kind": "practice"},
  {"id": "prac-sc-80", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. In case (b), the COM velocity and angular velocity are:", "options": ["$\\frac{\\Delta p}{M}$; $\\frac{\\Delta p}{2Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{Ml}$", "$\\frac{\\Delta p}{2M}$; 0", "$\\frac{\\Delta p}{M}$; 0"], "answer": 2, "hint": "An impulse along the rod has no moment about the COM.", "solution": "$v=\\frac{\\Delta p}{2M}$, ω = 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q80", "kind": "practice"},
  {"id": "prac-sc-81", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. The energies given to the dumbbell in cases (a) and (b) are:", "options": ["$\\frac{(\\Delta p)^2}{2M}$; $\\frac{(\\Delta p)^2}{4M}$", "$\\frac{(\\Delta p)^2}{4M}$; $\\frac{(\\Delta p)^2}{2M}$", "$\\frac{(\\Delta p)^2}{2M}$; $\\frac{(\\Delta p)^2}{2M}$", "$\\frac{(\\Delta p)^2}{4M}$; $\\frac{(\\Delta p)^2}{4M}$"], "answer": 0, "hint": "Add translational and rotational KE.", "solution": "(a) $\\frac{\\Delta p^2}{4M}+\\frac12\\cdot\\frac{Ml^2}{2}\\cdot\\frac{\\Delta p^2}{M^2l^2}=\\frac{\\Delta p^2}{2M}$; (b) $\\frac{\\Delta p^2}{4M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q81", "kind": "practice"},
  {"id": "prac-sc-82", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. The new trajectory is:", "options": ["parabolic", "elliptic", "hyperbolic", "circular"], "answer": 1, "hint": "Compare the new energy with zero.", "solution": "$E=-\\frac12mv_0^2(1-\\beta^2)<0$ and the orbit is no longer circular ⇒ ellipse.", "source": "Sri Chaitanya · Total Physics Important Questions · Q82", "kind": "practice"},
  {"id": "prac-sc-83", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 5, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. The minimum distance of the satellite from the Earth's centre is:", "options": ["$\\frac{\\beta r_0}{2}$", "$\\frac{r_0}{1+\\beta^2}$", "$\\frac{r_0}{1+\\beta}$", "$\\frac{r_0}{1+\\sqrt{2\\beta}}$"], "answer": 2, "hint": "A radial kick keeps L, so the semi-latus rectum stays $r_0$.", "solution": "Eccentricity $\\varepsilon=\\beta$, so $r_{min}=\\frac{l}{1+\\varepsilon}=\\frac{r_0}{1+\\beta}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q83", "kind": "practice"},
  {"id": "prac-sc-84", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 5, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. For β = 1/4, the new period is about (the original period is 24 h):", "options": ["20 h", "26 h", "67.9 h", "48 h"], "answer": 1, "hint": "Semi-major axis $=\\frac{r_0}{1-\\beta^2}$; Kepler's third law.", "solution": "$a=\\frac{16}{15}r_0$ ⇒ $T=24\\left(\\frac{16}{15}\\right)^{3/2}\\approx26$ h.", "source": "Sri Chaitanya · Total Physics Important Questions · Q84", "kind": "practice"},
  {"id": "prac-sc-85", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 2, "q": "A particle of mass m is on the axis of a thin ring (mass M, radius a), at a distance x from its centre. The gravitational potential energy of the system is:", "options": ["$-\\frac{GMm}{\\sqrt{a^2+x^2}}$", "$\\frac{GMm}{a}$", "$\\frac{GMm}{x}$", "None of these"], "answer": 0, "hint": "Every element of the ring is at the same distance.", "solution": "$U=-\\frac{GMm}{\\sqrt{a^2+x^2}}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q85", "kind": "practice"},
  {"id": "prac-sc-86", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 1, "q": "A particle of mass m is on the axis of a thin ring (mass M, radius a), at a distance x from its centre. The force on m when x = 0 is:", "options": ["$\\frac{GMm}{x^2}$", "$\\frac{GMm\\,x}{\\sqrt{a^2+x^2}}$", "$\\frac{GMm\\,x}{(a^2+x^2)^{3/2}}$", "zero"], "answer": 3, "hint": "Symmetry at the centre.", "solution": "All pulls cancel at the centre ⇒ zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q86", "kind": "practice"},
  {"id": "prac-sc-88", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The path traced by the projected particle is:", "options": ["circle", "ellipse", "straight line", "none of these"], "answer": 1, "hint": "Its speed is $\\sqrt{5/4}\\,v_0$: between orbital and escape speed.", "solution": "$v_0<v<\\sqrt2v_0$ ⇒ ellipse.", "source": "Sri Chaitanya · Total Physics Important Questions · Q88", "kind": "practice"},
  {"id": "prac-sc-89", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The particle's minimum distance from the Earth's centre is:", "options": ["a", "a/2", "3a", "5a/4"], "answer": 0, "hint": "It is launched tangentially, so the launch point is an apsis.", "solution": "Faster than circular speed ⇒ launch point is the perigee: a.", "source": "Sri Chaitanya · Total Physics Important Questions · Q89", "kind": "practice"},
  {"id": "prac-sc-90", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 4, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The particle's maximum distance from the Earth's centre is:", "options": ["a", "5a/4", "infinity", "5a/3"], "answer": 3, "hint": "Use energy and angular momentum conservation between the apsides.", "solution": "With r = ka: $3k^2-8k+5=0$ ⇒ k = 5/3.", "source": "Sri Chaitanya · Total Physics Important Questions · Q90", "kind": "practice"},
  {"id": "prac-sc-91", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 2, "q": "A person brings a 1 kg mass from infinity (at rest) to point A, where it moves at 2 m/s. The work done by the person is −3 J. The gravitational potential at A is:", "options": ["−3 J/kg", "−2 J/kg", "−5 J/kg", "−7 J/kg"], "answer": 2, "hint": "$W_{person}+W_{gravity}=\\Delta K$.", "solution": "$W_g=2+3=5$ J ⇒ $U_A=-5$ J ⇒ V = −5 J/kg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q91", "kind": "practice"},
  {"id": "prac-sc-92", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 1, "q": "The gravitational potential inside a hollow sphere (mass M, radius R) at distance r from its centre is:", "options": ["zero", "$-\\frac{GM}{R}$", "$-\\frac{GM}{r}$", "$-\\frac{GM}{r^2}$"], "answer": 1, "hint": "The field inside is zero.", "solution": "Constant potential equal to its surface value: $-GM/R$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q92", "kind": "practice"},
  {"id": "prac-sc-100", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 4, "q": "Poiseuille's equation gives the volume flow rate through a narrow tube as $Q=\\frac{\\pi P r^4}{8\\eta\\ell}$. Take the viscosity of blood as $4\\times10^{-3}$ N s/m². A major artery of radius 0.4 cm carries blood at 5 cm³/s. The pressure difference per metre of artery is about (density of mercury 13.6 g/cm³):", "options": ["9.6 mm of Hg", "3.2 mm of Hg", "1.5 mm of Hg", "8.6 mm of Hg"], "answer": 2, "hint": "$\\frac{P}{\\ell}=\\frac{8\\eta Q}{\\pi r^4}$.", "solution": "$\\frac{8\\times4\\times10^{-3}\\times5\\times10^{-6}}{\\pi(4\\times10^{-3})^4}\\approx199$ Pa/m ≈ 1.5 mm Hg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q100", "kind": "practice"},
  {"id": "prac-sc-101", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "Poiseuille's equation gives the volume flow rate through a narrow tube as $Q=\\frac{\\pi P r^4}{8\\eta\\ell}$. Take the viscosity of blood as $4\\times10^{-3}$ N s/m². If the average arterial pressure is about 100 mm of Hg, the 1.5 mm Hg per metre drop found for a major artery suggests:", "options": ["viscous effects are significant, so Bernoulli's equation doesn't apply", "viscous effects are insignificant in major arteries, so Bernoulli's equation applies", "it's impossible to judge", "Bernoulli's equation doesn't depend on viscosity"], "answer": 1, "hint": "Compare 1.5 with 100.", "solution": "The viscous drop is tiny compared with the pressure, so viscosity can be neglected.", "source": "Sri Chaitanya · Total Physics Important Questions · Q101", "kind": "practice"},
  {"id": "prac-sc-102", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "The average blood pressure at the heart is 100 mm of Hg. Taking blood density $10^3$ kg/m³ and g = 10 m/s², the average pressure in the leg of a standing person 1 m below the heart is nearly:", "options": ["92 mm of Hg", "100 mm of Hg", "144 mm of Hg", "174 mm of Hg"], "answer": 3, "hint": "Add ρgh and convert to mm Hg.", "solution": "$\\rho gh=10^4$ Pa ≈ 74 mm Hg ⇒ 174 mm Hg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q102", "kind": "practice"},
  {"id": "prac-sc-106", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). The speed of efflux is:", "options": ["4 m/s", "5 m/s", "6 m/s", "2 m/s"], "answer": 0, "hint": "Gauge pressure at the hole: $\\rho_2gh+\\rho_1g(h-y)$.", "solution": "$3600+3600=7200$ Pa $=\\frac12\\rho_1v^2$ ⇒ v = 4 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q106", "kind": "practice"},
  {"id": "prac-sc-107", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). If the tank rests on a smooth floor, the horizontal force F needed to keep it in equilibrium is:", "options": ["5.2 N", "7.2 N", "6.2 N", "8.2 N"], "answer": 1, "hint": "Thrust of the jet = $\\rho av^2$.", "solution": "$900\\times5\\times10^{-4}\\times16=7.2$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q107", "kind": "practice"},
  {"id": "prac-sc-108", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 4, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). If the friction coefficient with the floor is 0.01, the maximum F (applied on the side opposite the hole) that keeps the tank at rest is:", "options": ["62.2 N", "32.2 N", "52.2 N", "42.2 N"], "answer": 2, "hint": "Weight of liquids = $(900+600)\\times0.5\\times0.6\\times10$.", "solution": "Weight 4500 N ⇒ friction up to 45 N ⇒ $F_{max}=7.2+45=52.2$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q108", "kind": "practice"},
  {"id": "prac-sc-109", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A 2 kg ball is released from the bottom of a tank of water (ideal liquid) 2 m deep. On reaching the surface its kinetic energy is 16 J. Only gravity and upthrust act (g = 10 m/s²). Choose the INCORRECT option:", "options": ["Work done by gravity is −40 J", "Work done by upthrust is 56 J", "The work–energy theorem can be applied", "A free-falling observer finds the work done by gravity on the ball is zero"], "answer": 3, "hint": "Work depends on displacement in that frame.", "solution": "(A),(B),(C) are true (56 − 40 = 16). In the free-falling frame the ball still moves relative to the observer, so gravity's work is not zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q109", "kind": "practice"},
  {"id": "prac-sc-111", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A 2 kg ball is released from the bottom of a tank of water (ideal liquid) 2 m deep. On reaching the surface its kinetic energy is 16 J. Only gravity and upthrust act (g = 10 m/s²). Select the correct option:", "options": ["In gravity-free space the upthrust is non-zero", "From bottom to top the ball's acceleration is variable", "The ball's material is less dense than water", "Upthrust does not depend on g"], "answer": 2, "hint": "Upthrust (28 N) vs weight (20 N).", "solution": "$W_{up}=56$ J over 2 m ⇒ 28 N > 20 N ⇒ ball is less dense than water. Upthrust ∝ g, and acceleration is constant.", "source": "Sri Chaitanya · Total Physics Important Questions · Q111", "kind": "practice"},
  {"id": "prac-sc-112", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 1, "q": "Four open containers of different shapes hold the same oil. Rank them by the pressure at depth h, greatest first:", "options": ["A, C, B", "B, A, C", "C, A, B", "All tie"], "answer": 3, "hint": "Hydrostatic pressure depends only on depth.", "solution": "$P=P_0+\\rho gh$ for all ⇒ all tie.", "source": "Sri Chaitanya · Total Physics Important Questions · Q112", "kind": "practice"},
  {"id": "prac-sc-113", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 1, "q": "A penguin floats in fluids of densities $\\rho_0$, $0.95\\rho_0$ and $1.1\\rho_0$. Rank the fluids by buoyant force on it, greatest first:", "options": ["1.1ρ₀, ρ₀, 0.95ρ₀", "0.95ρ₀, ρ₀, 1.1ρ₀", "ρ₀, 0.95ρ₀, 1.1ρ₀", "All tie"], "answer": 3, "hint": "It floats in each.", "solution": "Floating ⇒ buoyant force = weight in every case.", "source": "Sri Chaitanya · Total Physics Important Questions · Q113", "kind": "practice"},
  {"id": "prac-sc-114", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A penguin floats in fluids of densities $\\rho_0$, $0.95\\rho_0$ and $1.1\\rho_0$. Rank the fluids by the volume displaced, greatest first:", "options": ["1.1ρ₀, ρ₀, 0.95ρ₀", "0.95ρ₀, ρ₀, 1.1ρ₀", "ρ₀, 0.95ρ₀, 1.1ρ₀", "All tie"], "answer": 1, "hint": "Same buoyant force, $V=\\frac{W}{\\rho g}$.", "solution": "Least dense fluid needs the most volume.", "source": "Sri Chaitanya · Total Physics Important Questions · Q114", "kind": "practice"},
  {"id": "prac-sc-115", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. Once flow is established:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["$P_B>P_C$", "$P_B=P_C$", "$P_B<P_C$", "$P_B$ and $P_C$ can't be predicted"], "answer": 1, "hint": "Same height, same speed (uniform tube).", "solution": "Bernoulli ⇒ equal pressures.", "source": "Sri Chaitanya · Total Physics Important Questions · Q115", "kind": "practice"},
  {"id": "prac-sc-116", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. The flow speed depends on:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["$h_1$ only", "$h_2$ only", "both $h_1$ and $h_2$", "neither"], "answer": 1, "hint": "Apply Bernoulli from the free surface to E.", "solution": "$v=\\sqrt{2gh_2}$ since E is $h_2$ below the water level.", "source": "Sri Chaitanya · Total Physics Important Questions · Q116", "kind": "practice"},
  {"id": "prac-sc-117", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. The pressure at A is:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["greater than atmospheric", "equal to atmospheric", "less than atmospheric", "can't be predicted"], "answer": 2, "hint": "A is at surface level but the water there is moving.", "solution": "$P_A=P_0-\\frac12\\rho v^2<P_0$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q117", "kind": "practice"},
  {"id": "prac-sc-118", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. Which harmonic is this?", "options": ["2", "4", "6", "5"], "answer": 3, "hint": "Closed pipe: $L=\\frac{n\\lambda}{4}$, n odd.", "solution": "$n=\\frac{4\\times0.9}{0.72}=5$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q118", "kind": "practice"},
  {"id": "prac-sc-119", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 1, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. The distance between a node and the adjacent antinode (m) is closest to:", "options": ["0.18", "0.36", "0.27", "0.22"], "answer": 0, "hint": "It's λ/4.", "solution": "$0.72/4=0.18$ m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q119", "kind": "practice"},
  {"id": "prac-sc-120", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. The wavelength of the next higher overtone (m) is closest to:", "options": ["0.40", "0.58", "0.36", "0.51"], "answer": 3, "hint": "Next allowed harmonic is the 7th.", "solution": "$\\lambda=\\frac{4\\times0.9}{7}=0.51$ m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q120", "kind": "practice"},
  {"id": "prac-sc-121", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A wave pulse on a string travels in the −x direction as shown. Kinetic energy is maximum for particle:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["D", "E", "F", "G"], "answer": 1, "hint": "Speed is greatest where the slope is steepest.", "solution": "E is at the mean position of the steep part.", "source": "Sri Chaitanya · Total Physics Important Questions · Q121", "kind": "practice"},
  {"id": "prac-sc-122", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A wave pulse on a string travels in the −x direction as shown. Potential energy is maximum for particle:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["D", "E", "F", "G"], "answer": 1, "hint": "PE density ∝ (slope)².", "solution": "The string is most stretched at E.", "source": "Sri Chaitanya · Total Physics Important Questions · Q122", "kind": "practice"},
  {"id": "prac-sc-123", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A wave pulse on a string travels in the −x direction as shown. Particles B and D are moving respectively:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["up, up", "down, down", "up, down", "down, up"], "answer": 2, "hint": "For a wave moving in −x, $v_y=+v\\frac{\\partial y}{\\partial x}$.", "solution": "B is on a rising slope ⇒ up; D on a falling slope ⇒ down.", "source": "Sri Chaitanya · Total Physics Important Questions · Q123", "kind": "practice"},
  {"id": "prac-sc-124", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 4, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. The maximum displacement amplitude in the string is:", "options": ["10 mm", "$20/\\sqrt3$ mm", "$10\\sqrt3$ mm", "20 mm"], "answer": 0, "hint": "The two points sit symmetrically in a loop: $\\frac\\lambda2-20=10$.", "solution": "λ = 60 cm; $A\\sin\\frac{2\\pi(10)}{60}=5\\sqrt3$ ⇒ A = 10 mm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q124", "kind": "practice"},
  {"id": "prac-sc-125", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. The overtone produced is the:", "options": ["2nd", "3rd", "4th", "6th"], "answer": 2, "hint": "Count loops: $150/30$.", "solution": "5 loops ⇒ 5th harmonic ⇒ 4th overtone.", "source": "Sri Chaitanya · Total Physics Important Questions · Q125", "kind": "practice"},
  {"id": "prac-sc-126", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. At what minimum distance from one end is the string's potential energy zero (the end having maximum PE)?", "options": ["$10\\sqrt3$ cm", "15 cm", "20 cm", "30 cm"], "answer": 1, "hint": "PE is zero where the strain is zero: an antinode.", "solution": "Nearest antinode is λ/4 = 15 cm from the end.", "source": "Sri Chaitanya · Total Physics Important Questions · Q126", "kind": "practice"},
  {"id": "prac-sc-127", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A fighter plane moving at 300 m/s fires 40 rounds per second with a muzzle velocity of 1200 m/s (relative to the plane) at a target plane flying at 200 m/s along the same line. If the target is ahead and moving the same way, the rate (rounds/s) at which bullets hit it is:", "options": ["36.67", "43.33", "56.67", "23.33"], "answer": 1, "hint": "Spacing of bullets in air = (1500 − 300)/40.", "solution": "Spacing 30 m; closing speed 1500 − 200 = 1300 m/s ⇒ 43.33/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q127", "kind": "practice"},
  {"id": "prac-sc-128", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 4, "q": "A fighter plane moving at 300 m/s fires 40 rounds per second with a muzzle velocity of 1200 m/s (relative to the plane) at a target plane flying at 200 m/s along the same line. If the target is behind the shooter, moving the same way, and the gun fires backward at it, the rate is:", "options": ["36.67", "43.33", "56.67", "23.33"], "answer": 0, "hint": "Bullets move back at 900 m/s (ground); spacing 1200/40.", "solution": "Spacing 30 m, closing speed 900 + 200 ⇒ 36.67/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q128", "kind": "practice"},
  {"id": "prac-sc-129", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A fighter plane moving at 300 m/s fires 40 rounds per second with a muzzle velocity of 1200 m/s (relative to the plane) at a target plane flying at 200 m/s along the same line. If the planes approach each other, the rate is:", "options": ["36.67", "43.33", "56.67", "23.33"], "answer": 2, "hint": "Closing speed = 1500 + 200.", "solution": "1700/30 = 56.67/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q129", "kind": "practice"},
  {"id": "prac-sc-133", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A plane sinusoidal sound wave travels along +x at 120 cm/s with frequency 5 Hz. The graph shows the displacement S of the particles vs position x at t = 0 (amplitude 20 mm; S = 0 at x = −8 cm). The distance of point Q from the origin is:", "img": "figures/prac-sc-p45.png", "imgAlt": "Displacement–position graph at t = 0: zero at −8 cm, minimum at R, P at x = 0 below the axis, zero again at Q, then a crest", "options": ["2 cm", "3 cm", "4 cm", "1 cm"], "answer": 2, "hint": "λ = v/f; zeros are λ/2 apart.", "solution": "λ = 24 cm; zeros at −8 and −8 + 12 = 4 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q133", "kind": "practice"},
  {"id": "prac-sc-134", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 4, "q": "A plane sinusoidal sound wave travels along +x at 120 cm/s with frequency 5 Hz. The graph shows the displacement S of the particles vs position x at t = 0 (amplitude 20 mm; S = 0 at x = −8 cm). The velocity of particle P is:", "img": "figures/prac-sc-p45.png", "imgAlt": "Displacement–position graph at t = 0: zero at −8 cm, minimum at R, P at x = 0 below the axis, zero again at Q, then a crest", "options": ["$10\\sqrt3\\pi$ cm/s upward", "$10\\pi$ cm/s downward", "$10\\sqrt3\\pi$ cm/s right", "$10\\pi$ cm/s left"], "answer": 3, "hint": "Longitudinal wave: particle velocity is along x, $v_p=-v\\frac{\\partial S}{\\partial x}$.", "solution": "Slope at x = 0 is $\\frac{20k}{2}=\\frac{5\\pi}{6}$ mm/cm ⇒ $v_p=-120\\times\\frac{5\\pi}{6}$ mm/s = −10π cm/s (left).", "source": "Sri Chaitanya · Total Physics Important Questions · Q134", "kind": "practice"},
  {"id": "prac-sc-135", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 5, "q": "A plane sinusoidal sound wave travels along +x at 120 cm/s with frequency 5 Hz. The graph shows the displacement S of the particles vs position x at t = 0 (amplitude 20 mm; S = 0 at x = −8 cm). The velocity of particle R when P reaches its mean position is:", "img": "figures/prac-sc-p45.png", "imgAlt": "Displacement–position graph at t = 0: zero at −8 cm, minimum at R, P at x = 0 below the axis, zero again at Q, then a crest", "options": ["$10\\sqrt3\\pi$ cm/s upward", "$10\\pi$ cm/s downward", "$10\\sqrt3\\pi$ cm/s right", "$10\\pi$ cm/s left"], "answer": 2, "hint": "Write $S=-20\\sin k(x+8-vt)$ mm and advance the phase.", "solution": "P reaches the mean after a phase change of 2π/3; R's phase is then −π/6 ⇒ $v=20\\omega\\cos\\frac\\pi6=10\\sqrt3\\pi$ cm/s along +x.", "source": "Sri Chaitanya · Total Physics Important Questions · Q135", "kind": "practice"},
  {"id": "prac-sc-136", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A plane longitudinal wave of angular frequency 500 rad/s travels in +x through a medium of density 0.16 kg/m³ and bulk modulus $4\\times10^4$ N/m². The loudness at a point is 20 dB (reference $10^{-12}$ W/m²). The speed of the wave is:", "options": ["500 m/s", "250 m/s", "100 m/s", "50 m/s"], "answer": 0, "hint": "$v=\\sqrt{B/\\rho}$.", "solution": "$\\sqrt{4\\times10^4/0.16}=500$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q136", "kind": "practice"},
  {"id": "prac-sc-137", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 4, "q": "A plane longitudinal wave of angular frequency 500 rad/s travels in +x through a medium of density 0.16 kg/m³ and bulk modulus $4\\times10^4$ N/m². The loudness at a point is 20 dB (reference $10^{-12}$ W/m²). The displacement amplitude (nm) is about:", "options": ["2.0", "3.0", "5.0", "8.0"], "answer": 1, "hint": "$I=\\frac12\\rho\\omega^2A^2v$ with $I=10^{-10}$ W/m².", "solution": "$A^2=\\frac{2\\times10^{-10}}{0.16\\times2.5\\times10^5\\times500}=10^{-17}$ ⇒ A ≈ 3.2 nm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q137", "kind": "practice"},
  {"id": "prac-sc-139", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A string of linear density $4\\times10^{-3}$ kg/m under 360 N tension is fixed at both ends. Two consecutive resonance frequencies are 375 Hz and 450 Hz. The length of the string is:", "options": ["2 m", "4 m", "0.5 m", "1 m"], "answer": 0, "hint": "Fundamental = difference of consecutive resonances.", "solution": "$v=300$ m/s, $f_1=75$ Hz ⇒ $L=\\frac{v}{2f_1}=2$ m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q139", "kind": "practice"},
  {"id": "prac-sc-140", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A string of linear density $4\\times10^{-3}$ kg/m under 360 N tension is fixed at both ends. Two consecutive resonance frequencies are 375 Hz and 450 Hz. When it resonates close to 1000 Hz, which overtone is it?", "options": ["14th", "13th", "11th", "12th"], "answer": 3, "hint": "Harmonics are multiples of 75 Hz.", "solution": "975 Hz = 13th harmonic = 12th overtone.", "source": "Sri Chaitanya · Total Physics Important Questions · Q140", "kind": "practice"},
  {"id": "prac-sc-142", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A person between two tall parallel cliffs claps; the first two echoes are heard after 2 s and 3 s. Speed of sound 330 m/s. The separation between the cliffs is:", "options": ["825 m", "800 m", "725 m", "600 m"], "answer": 0, "hint": "Each echo travels twice the distance to its cliff.", "solution": "$d_1=330$ m, $d_2=495$ m ⇒ 825 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q142", "kind": "practice"},
  {"id": "prac-sc-143", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A person between two tall parallel cliffs claps; the first two echoes are heard after 2 s and 3 s. Speed of sound 330 m/s. The third echo is heard at:", "options": ["3 s", "5 s", "2.5 s", "2 s"], "answer": 1, "hint": "Sound reflected by one cliff then the other.", "solution": "Path $2d_1+2d_2$ ⇒ 2 + 3 = 5 s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q143", "kind": "practice"},
  {"id": "prac-sc-145", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A string 3 m long ($\\mu=25\\times10^{-3}$ kg/m) is tied to a rigid support at one end and to a light thread (acting as a free end) at the other; its tension is 160 N. It vibrates in its first overtone and drives a closed organ pipe 3 m long (containing an unknown gas) in its fundamental mode. The speed of the wave in the string is:", "options": ["40 m/s", "100 m/s", "120 m/s", "none of these"], "answer": 3, "hint": "$v=\\sqrt{T/\\mu}$.", "solution": "$\\sqrt{160/0.025}=80$ m/s: not listed.", "source": "Sri Chaitanya · Total Physics Important Questions · Q145", "kind": "practice"},
  {"id": "prac-sc-146", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 3 m long ($\\mu=25\\times10^{-3}$ kg/m) is tied to a rigid support at one end and to a light thread (acting as a free end) at the other; its tension is 160 N. It vibrates in its first overtone and drives a closed organ pipe 3 m long (containing an unknown gas) in its fundamental mode. The frequency of the string is:", "options": ["30 Hz", "40 Hz", "20 Hz", "none of these"], "answer": 2, "hint": "Fixed–free string: first overtone has $L=\\frac{3\\lambda}{4}$.", "solution": "λ = 4 m ⇒ f = 80/4 = 20 Hz.", "source": "Sri Chaitanya · Total Physics Important Questions · Q146", "kind": "practice"},
  {"id": "prac-sc-147", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 3 m long ($\\mu=25\\times10^{-3}$ kg/m) is tied to a rigid support at one end and to a light thread (acting as a free end) at the other; its tension is 160 N. It vibrates in its first overtone and drives a closed organ pipe 3 m long (containing an unknown gas) in its fundamental mode. The speed of sound in the gas is:", "options": ["340 m/s", "240 m/s", "200 m/s", "none of these"], "answer": 1, "hint": "Closed pipe fundamental: $L=\\lambda/4$.", "solution": "λ = 12 m, f = 20 Hz ⇒ 240 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q147", "kind": "practice"},
  {"id": "prac-sc-148", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "The displacement in a sound wave is $y_1=A\\cos(ax+bt)$ (A, a, b positive). It is reflected by an obstacle at x = 0; the reflected intensity is 0.64 times the incident intensity. The reflected wave is:", "options": ["$0.8A\\sin(bt-ax)$", "$0.8A\\cos(bt-ax)$", "$-0.8A\\cos(bt-ax)$", "$-0.8A\\sin(bt-ax)$"], "answer": 2, "hint": "Amplitude ∝ √I; a rigid obstacle inverts displacement.", "solution": "Amplitude 0.8A, travelling +x, phase-inverted ⇒ $-0.8A\\cos(bt-ax)$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q148", "kind": "practice"},
  {"id": "prac-sc-149", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "The displacement in a sound wave is $y_1=A\\cos(ax+bt)$ (A, a, b positive). It is reflected by an obstacle at x = 0; the reflected intensity is 0.64 times the incident intensity. In the resultant wave, the maximum and minimum particle speeds are:", "options": ["1.8Ab and 0.2Ab", "1.6Ab and 0.1Ab", "1.4Ab and 0.1Ab", "1.2Ab and 0.2Ab"], "answer": 0, "hint": "Amplitudes add at antinodes and subtract at nodes.", "solution": "Amplitude ranges from 1.8A to 0.2A ⇒ speeds 1.8Ab and 0.2Ab.", "source": "Sri Chaitanya · Total Physics Important Questions · Q149", "kind": "practice"},
  {"id": "prac-sc-154", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "Increasing the tension in a string by 21% changes its fundamental frequency by 15 Hz. The original fundamental frequency is about:", "options": ["150 Hz", "100 Hz", "120 Hz", "50 Hz"], "answer": 0, "hint": "$f\\propto\\sqrt T$: ×1.1.", "solution": "$0.1f=15$ ⇒ 150 Hz.", "source": "Sri Chaitanya · Total Physics Important Questions · Q154", "kind": "practice"},
  {"id": "prac-sc-155", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 1, "q": "Increasing the tension in a string by 21% changes its fundamental frequency by 15 Hz. The wave speed changes by nearly:", "options": ["5%", "10%", "20%", "25%"], "answer": 1, "hint": "$v\\propto\\sqrt T$.", "solution": "$\\sqrt{1.21}=1.1$ ⇒ 10%.", "source": "Sri Chaitanya · Total Physics Important Questions · Q155", "kind": "practice"},
  {"id": "prac-sc-156", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 1, "q": "Increasing the tension in a string by 21% changes its fundamental frequency by 15 Hz. The fundamental wavelength changes by:", "options": ["5%", "10%", "20%", "0%"], "answer": 3, "hint": "It depends only on the string's length.", "solution": "λ = 2L, unchanged.", "source": "Sri Chaitanya · Total Physics Important Questions · Q156", "kind": "practice"},
  {"id": "prac-sc-157", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "A particle moves along the x-axis as $x=a\\sin^2\\left(\\omega t-\\frac\\pi4\\right)$. The amplitude of oscillation is:", "options": ["a", "a/2", "3a/2", "2a"], "answer": 1, "hint": "$\\sin^2\\phi=\\frac{1-\\cos2\\phi}{2}$.", "solution": "$x=\\frac a2-\\frac a2\\cos(2\\omega t-\\frac\\pi2)$ ⇒ amplitude a/2.", "source": "Sri Chaitanya · Total Physics Important Questions · Q157", "kind": "practice"},
  {"id": "prac-sc-159", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 3, "q": "A particle moves along the x-axis as $x=a\\sin^2\\left(\\omega t-\\frac\\pi4\\right)$. The velocity u as a function of x is:", "options": ["$u^2=4\\omega^2x(a-x)$", "$u^2=2\\omega^2x(a-x)$", "$u^2=\\omega^2x(a-x)$", "$u^2=8\\omega^2x(a-x)$"], "answer": 0, "hint": "Angular frequency 2ω, mean a/2, amplitude a/2.", "solution": "$u^2=4\\omega^2\\left[\\frac{a^2}4-(x-\\frac a2)^2\\right]=4\\omega^2x(a-x)$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q159", "kind": "practice"},
  {"id": "prac-sc-160", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "Block A (1 kg, neutral) is attached to a spring (k = 18 N/m) fixed to a wall on its left; A is at x = 0 with the spring relaxed. Block B (1 kg, charge −1 C) is released from rest at x = 1.8 m in a uniform field E = 10 N/C along +x. Ignore friction. If A and B stick on collision, the velocity just after is:", "options": ["6 m/s", "3 m/s", "9 m/s", "12 m/s"], "answer": 1, "hint": "B accelerates at 10 m/s² over 1.8 m.", "solution": "$v_B=6$ m/s ⇒ combined 3 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q160", "kind": "practice"},
  {"id": "prac-sc-161", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "Block A (1 kg, neutral) is attached to a spring (k = 18 N/m) fixed to a wall on its left; A is at x = 0 with the spring relaxed. Block B (1 kg, charge −1 C) is released from rest at x = 1.8 m in a uniform field E = 10 N/C along +x. Ignore friction. The equilibrium position of the combined mass is at x =", "options": ["−2/9 m", "−1/3 m", "−5/9 m", "−7/9 m"], "answer": 2, "hint": "Spring force balances the 10 N electric force.", "solution": "18x = −10 ⇒ x = −5/9 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q161", "kind": "practice"},
  {"id": "prac-sc-162", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 3, "q": "Block A (1 kg, neutral) is attached to a spring (k = 18 N/m) fixed to a wall on its left; A is at x = 0 with the spring relaxed. Block B (1 kg, charge −1 C) is released from rest at x = 1.8 m in a uniform field E = 10 N/C along +x. Ignore friction. The amplitude of oscillation of the combined mass is:", "options": ["2/3 m", "$\\frac{\\sqrt{124}}{3}$ m", "$\\frac{\\sqrt{72}}{9}$ m", "$\\frac{\\sqrt{106}}{9}$ m"], "answer": 3, "hint": "ω² = 18/2 = 9; at x = 0 it is 5/9 m from equilibrium with speed 3.", "solution": "$A^2=(5/9)^2+(3/3)^2=\\frac{106}{81}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q162", "kind": "practice"},
  {"id": "prac-sc-163", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "Blocks m and 2m on a frictionless floor are joined by a spring (relaxed length l, stiffness k), held compressed to l/2 by a thread. The system moves at speed v perpendicular to the spring. Then the thread is burnt. Before burning, the ratio of kinetic to potential energy is:", "options": ["$\\frac{12mv^2}{kl^2}$", "$\\frac{mv^2}{12kl^2}$", "$\\frac{12kl^2}{mv^2}$", "$\\frac{kl^2}{12mv^2}$"], "answer": 0, "hint": "KE of 3m; spring compressed by l/2.", "solution": "$\\frac{\\frac32mv^2}{\\frac18kl^2}=\\frac{12mv^2}{kl^2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q163", "kind": "practice"},
  {"id": "prac-sc-164", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 1, "q": "Blocks m and 2m on a frictionless floor are joined by a spring (relaxed length l, stiffness k), held compressed to l/2 by a thread. The system moves at speed v perpendicular to the spring. Then the thread is burnt. After burning the thread, the speed of the centre of mass is:", "options": ["less than v", "greater than v", "equal to v", "$\\frac{2}{\\sqrt3}v$"], "answer": 2, "hint": "No external horizontal force.", "solution": "COM velocity is unchanged: v.", "source": "Sri Chaitanya · Total Physics Important Questions · Q164", "kind": "practice"},
  {"id": "prac-sc-165", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "Blocks m and 2m on a frictionless floor are joined by a spring (relaxed length l, stiffness k), held compressed to l/2 by a thread. The system moves at speed v perpendicular to the spring. Then the thread is burnt. The period of oscillation is:", "options": ["$2\\pi\\sqrt{\\frac{2m}{3k}}$", "$2\\pi\\sqrt{\\frac{3m}{2k}}$", "$2\\pi\\sqrt{\\frac{3m}{k}}$", "$\\pi\\sqrt{\\frac{2m}{3k}}$"], "answer": 0, "hint": "Use the reduced mass.", "solution": "$\\mu=\\frac{2m}{3}$ ⇒ $T=2\\pi\\sqrt{\\frac{2m}{3k}}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q165", "kind": "practice"},
  {"id": "prac-sc-170", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "For SHM, $x=A\\sin(\\omega t+\\theta)$ with $\\omega=2\\pi/T$. The average velocity from one extreme to the other (v = maximum speed) is:", "options": ["$\\frac{2v}{\\pi}$", "$\\frac{2A}{t}$", "$\\frac{3A}{t}$", "$\\frac v\\pi$"], "answer": 0, "hint": "Displacement 2A in T/2.", "solution": "$\\frac{4A}{T}=\\frac{4A}{2\\pi A/v}=\\frac{2v}{\\pi}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q170", "kind": "practice"},
  {"id": "prac-sc-171", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 1, "q": "For SHM, $x=A\\sin(\\omega t+\\theta)$ with $\\omega=2\\pi/T$. The acceleration is half its maximum value at a displacement of:", "options": ["$\\frac{A}{\\sqrt2}$", "$\\frac{\\sqrt3A}{2}$", "$\\frac{A}{\\sqrt3}$", "$\\frac A2$"], "answer": 3, "hint": "a ∝ x.", "solution": "x = A/2.", "source": "Sri Chaitanya · Total Physics Important Questions · Q171", "kind": "practice"},
  {"id": "prac-sc-172", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "A spring of constant K with a mass has period T. The spring is cut into three equal parts. If the three parts are joined in parallel, the period for the same mass is:", "options": ["T", "T/3", "T/9", "2T/3"], "answer": 1, "hint": "Each part has constant 3K.", "solution": "Parallel: 9K ⇒ T/3.", "source": "Sri Chaitanya · Total Physics Important Questions · Q172", "kind": "practice"},
  {"id": "prac-sc-174", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 1, "q": "A spring of constant K with a mass has period T. The spring is cut into three equal parts. Comparing the parts joined in series with the parts joined in parallel, for the same load the frequency is:", "options": ["the same", "more in series", "more in parallel", "can't say"], "answer": 2, "hint": "Parallel is stiffer.", "solution": "9K > K ⇒ higher frequency in parallel.", "source": "Sri Chaitanya · Total Physics Important Questions · Q174", "kind": "practice"},
  {"id": "prac-sc-175", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 3, "q": "Two light vertical springs of stiffness K and 2K support a light horizontal rod. A bead of mass m is placed gently at the midpoint of the rod and lowered slowly till it rests. The energy of oscillation of the bead for amplitude $y_0$ is:", "options": ["$mgx_0$", "$mg(x_0+y_0)$", "$\\frac32Ky_0^2$", "$\\frac43Ky_0^2$"], "answer": 3, "hint": "Effective stiffness at the midpoint.", "solution": "Midpoint moves $\\frac12\\left(\\frac{F}{2K}+\\frac{F}{4K}\\right)=\\frac{3F}{8K}$ ⇒ $k=\\frac{8K}{3}$ ⇒ $E=\\frac43Ky_0^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q175", "kind": "practice"},
  {"id": "prac-sc-176", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 3, "q": "Two light vertical springs of stiffness K and 2K support a light horizontal rod. A bead of mass m is placed gently at the midpoint of the rod and lowered slowly till it rests. The period of SHM of the bead is:", "options": ["$2\\pi\\sqrt{\\frac{3m}{8K}}$", "$2\\pi\\sqrt{\\frac{m}{3K}}$", "$3\\pi\\sqrt{\\frac{2m}{K}}$", "None of these"], "answer": 0, "hint": "$k_{eff}=\\frac{8K}{3}$.", "solution": "$T=2\\pi\\sqrt{\\frac{3m}{8K}}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q176", "kind": "practice"},
  {"id": "prac-sc-177", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 3, "q": "Two light vertical springs of stiffness K and 2K support a light horizontal rod. A bead of mass m is placed gently at the midpoint of the rod and lowered slowly till it rests. The ratio of the work done by the external agent to that by gravity (magnitudes) while lowering the bead to rest is:", "options": ["1 : 1", "1 : 2", "2 : 1", "1 : 4"], "answer": 1, "hint": "Spring stores half of mgx at equilibrium.", "solution": "Gravity: mgx; spring: ½mgx; agent: −½mgx ⇒ 1 : 2.", "source": "Sri Chaitanya · Total Physics Important Questions · Q177", "kind": "practice"},
  {"id": "prac-sc-178", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "The velocity–displacement graph of a particle in SHM is an ellipse with $v_{max}=10$ m/s and $x_{max}=2.5$ m. The period of motion is:", "options": ["π/4 s", "π/2 s", "π s", "2π s"], "answer": 1, "hint": "$\\omega=v_{max}/A$.", "solution": "ω = 4 rad/s ⇒ T = π/2 s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q178", "kind": "practice"},
  {"id": "prac-sc-179", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 1, "q": "The velocity–displacement graph of a particle in SHM is an ellipse with $v_{max}=10$ m/s and $x_{max}=2.5$ m. The maximum acceleration is:", "options": ["10 m/s²", "20 m/s²", "30 m/s²", "40 m/s²"], "answer": 3, "hint": "$\\omega^2A$.", "solution": "16 × 2.5 = 40 m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q179", "kind": "practice"},
  {"id": "prac-sc-180", "exam": "JEE", "subject": "Physics", "chapter": "Oscillations", "type": "mcq", "difficulty": 2, "q": "The velocity–displacement graph of a particle in SHM is an ellipse with $v_{max}=10$ m/s and $x_{max}=2.5$ m. The speed at 1.5 m from the mean position is:", "options": ["4 m/s", "8 m/s", "12 m/s", "16 m/s"], "answer": 1, "hint": "$v=\\omega\\sqrt{A^2-x^2}$.", "solution": "$4\\sqrt{6.25-2.25}=8$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q180", "kind": "practice"},
  {"id": "prac-sc-181", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "From left to right: an observer, a convex lens (f = +30 cm), an erect object 20 mm high, and a convex mirror (R = 80 cm). The object is 20 cm from the lens and 50 cm from the mirror. The observer sees the image formed first by the mirror and then by the lens. The intermediate image formed by the mirror is:", "options": ["virtual and diminished", "real and erect", "indeterminate", "virtual and inverted"], "answer": 0, "hint": "Convex mirror, f = +40 cm.", "solution": "v ≈ +22.2 cm (behind), m ≈ 0.44: virtual, erect, diminished.", "source": "Sri Chaitanya · Total Physics Important Questions · Q181", "kind": "practice"},
  {"id": "prac-sc-183", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "From left to right: an observer, a convex lens (f = +30 cm), an erect object 20 mm high, and a convex mirror (R = 80 cm). The object is 20 cm from the lens and 50 cm from the mirror. The observer sees the image formed first by the mirror and then by the lens. The final image, relative to the erect object, is:", "options": ["real and erect", "indeterminate", "real and inverted", "virtual and erect"], "answer": 2, "hint": "The mirror image is ~72 cm from the lens, beyond f.", "solution": "The lens forms a real image of it, inverted relative to the (erect) intermediate image.", "source": "Sri Chaitanya · Total Physics Important Questions · Q183", "kind": "practice"},
  {"id": "prac-sc-184", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A man faces a plane mirror on the front wall of a room and wants to see the whole back wall (height H) behind him. Standing against the back wall, the minimum mirror length needed is:", "options": ["H", "H/2", "H/3", "H/4"], "answer": 1, "hint": "Mirror length $=H\\frac{b}{a+2b}$ (a: man to back wall, b: man to mirror).", "solution": "a = 0 ⇒ H/2.", "source": "Sri Chaitanya · Total Physics Important Questions · Q184", "kind": "practice"},
  {"id": "prac-sc-185", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A man faces a plane mirror on the front wall of a room and wants to see the whole back wall (height H) behind him. Standing midway between the walls, the minimum mirror length needed is:", "options": ["H", "H/2", "H/3", "H/4"], "answer": 2, "hint": "a = b.", "solution": "$\\frac{b}{3b}H=H/3$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q185", "kind": "practice"},
  {"id": "prac-sc-186", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A man faces a plane mirror on the front wall of a room and wants to see the whole back wall (height H) behind him. Standing twice as far from the back wall as from the mirror, the minimum mirror length is:", "options": ["H", "H/2", "H/3", "H/4"], "answer": 3, "hint": "a = 2b.", "solution": "$\\frac{b}{4b}H=H/4$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q186", "kind": "practice"},
  {"id": "prac-sc-187", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "An object is on the axis of a concave mirror (f = 20 cm), 30 cm from it. The image is:", "options": ["60 cm in front of the mirror", "60 cm behind the mirror", "12 cm in front", "12 cm behind"], "answer": 0, "hint": "Mirror formula with u = −30, f = −20.", "solution": "v = −60 cm: real, in front.", "source": "Sri Chaitanya · Total Physics Important Questions · Q187", "kind": "practice"},
  {"id": "prac-sc-188", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "An object is on the axis of a concave mirror (f = 20 cm), 30 cm from it. If the object moves towards the mirror along the axis at 2 cm/s, the image:", "options": ["moves away from the mirror at 8 cm/s", "moves towards it at 8 cm/s", "moves towards it at 4 cm/s", "moves away at 4 cm/s"], "answer": 0, "hint": "$v_{image}=-m^2v_{object}$.", "solution": "m = −2 ⇒ image speed 8 cm/s, away from the mirror.", "source": "Sri Chaitanya · Total Physics Important Questions · Q188", "kind": "practice"},
  {"id": "prac-sc-189", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "An object is on the axis of a concave mirror (f = 20 cm), 30 cm from it. If the object moves perpendicular to the axis (upward) at 2 cm/s, the image moves:", "options": ["at 4 cm/s below the axis", "at 4 cm/s above", "at 8 cm/s below", "at 8 cm/s above"], "answer": 0, "hint": "Transverse image velocity = m × object velocity.", "solution": "m = −2 ⇒ 4 cm/s downward.", "source": "Sri Chaitanya · Total Physics Important Questions · Q189", "kind": "practice"},
  {"id": "prac-sc-190", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "Real images of an object are formed on a screen 180 cm away for two positions of a lens 60 cm apart. The focal length of the lens is:", "options": ["40 cm", "25 cm", "14 cm", "20 cm"], "answer": 0, "hint": "$f=\\frac{D^2-d^2}{4D}$.", "solution": "$\\frac{32400-3600}{720}=40$ cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q190", "kind": "practice"},
  {"id": "prac-sc-191", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "Real images of an object are formed on a screen 180 cm away for two positions of a lens 60 cm apart. The ratio of the sizes of the two images is:", "options": ["1/3", "3", "1/4", "1/2"], "answer": 2, "hint": "Positions: u = 60, v = 120 and vice versa.", "solution": "m = 2 and 1/2 ⇒ ratio 1/4.", "source": "Sri Chaitanya · Total Physics Important Questions · Q191", "kind": "practice"},
  {"id": "prac-sc-192", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "In the displacement method, the two images have sizes 0.4 cm and 0.9 cm. The size of the object is:", "options": ["0.36 cm", "0.6 cm", "1.5 cm", "0.9 cm"], "answer": 1, "hint": "$O=\\sqrt{I_1I_2}$.", "solution": "$\\sqrt{0.36}=0.6$ cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q192", "kind": "practice"},
  {"id": "prac-sc-193", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A thin concavo-convex glass lens (μ = 1.5) has surface radii 10 cm and 50 cm. Its focal length (without silvering) is:", "options": ["25 cm", "20 cm", "10 cm", "5 cm"], "answer": 0, "hint": "Lens maker: $\\frac1f=(\\mu-1)\\left(\\frac1{10}-\\frac1{50}\\right)$.", "solution": "$0.5\\times0.08=0.04$ ⇒ 25 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q193", "kind": "practice"},
  {"id": "prac-sc-196", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "An object 25 cm high is in front of a convex lens (f = 30 cm); the image is 50 cm high. If the image is real and inverted, the image distance is:", "options": ["90 cm", "45 cm", "30 cm", "25 cm"], "answer": 0, "hint": "m = −2 ⇒ v = −2u.", "solution": "u = −45 cm ⇒ v = 90 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q196", "kind": "practice"},
  {"id": "prac-sc-197", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "An object 25 cm high is in front of a convex lens (f = 30 cm); the image is 50 cm high. If the image is erect and virtual, the image distance is:", "options": ["90 cm", "45 cm", "−30 cm", "−60 cm"], "answer": 2, "hint": "m = +2.", "solution": "u = −15 ⇒ v = −30 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q197", "kind": "practice"},
  {"id": "prac-sc-198", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "An object 25 cm high is in front of a convex lens (f = 30 cm); the image is 50 cm high. If the image is erect and virtual, the distance between object and image is:", "options": ["25 cm", "15 cm", "40 cm", "60 cm"], "answer": 1, "hint": "Both on the same side.", "solution": "30 − 15 = 15 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q198", "kind": "practice"},
  {"id": "prac-sc-199", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "Two thin convex lenses $L_1$ (focal length $f_1$) and $L_2$ ($f_2$) are a distance d apart ($d<f_1$, $d<f_2$); the centre of $L_2$ is displaced vertically by $x_0$ from the axis of $L_1$. Origin at the centre of $L_1$; a parallel paraxial beam comes from the left along the axis of $L_1$. For lens $L_2$, the object distance is:", "options": ["$f_2-f_1$", "$f_2+d$", "$f_1+d$", "$f_1-d$"], "answer": 3, "hint": "$L_1$ focuses the beam at $f_1$, beyond $L_2$.", "solution": "Virtual object at $f_1-d$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q199", "kind": "practice"},
  {"id": "prac-sc-200", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "Two thin convex lenses $L_1$ (focal length $f_1$) and $L_2$ ($f_2$) are a distance d apart ($d<f_1$, $d<f_2$); the centre of $L_2$ is displaced vertically by $x_0$ from the axis of $L_1$. Origin at the centre of $L_1$; a parallel paraxial beam comes from the left along the axis of $L_1$. The x-coordinate of the final image is:", "options": ["$\\frac{d(f_1-d)+f_1f_2}{f_1+f_2-d}$", "$\\frac{d(f_1+d)}{f_1+f_2-d}$", "$f_1+f_2$", "$\\frac{(f_1+f_2)d}{f_1-f_2+d}$"], "answer": 0, "hint": "$L_2$ images a virtual object at $u=f_1-d$.", "solution": "$v=\\frac{f_2(f_1-d)}{f_1+f_2-d}$; x = d + v simplifies to (A).", "source": "Sri Chaitanya · Total Physics Important Questions · Q200", "kind": "practice"},
  {"id": "prac-sc-201", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "Two thin convex lenses $L_1$ (focal length $f_1$) and $L_2$ ($f_2$) are a distance d apart ($d<f_1$, $d<f_2$); the centre of $L_2$ is displaced vertically by $x_0$ from the axis of $L_1$. Origin at the centre of $L_1$; a parallel paraxial beam comes from the left along the axis of $L_1$. The y-coordinate of the final image is:", "options": ["$x_0\\frac{f_1-d}{f_1+f_2-d}$", "$x_0$", "$\\frac{x_0(f_1+d)}{f_1+f_2}$", "$\\frac{x_0(f_1+f_2)}{f_1+f_2-d}$"], "answer": 0, "hint": "Object is $x_0$ below $L_2$'s axis; magnification $v/u$.", "solution": "$y=x_0-x_0\\frac{f_2}{f_1+f_2-d}=x_0\\frac{f_1-d}{f_1+f_2-d}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q201", "kind": "practice"},
  {"id": "prac-sc-202", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A zoom system: converging lens $f_1$, then a diverging lens $f_2=-|f_2|$ at distance d < $f_1$ with $|f_2|>f_1-d$. A parallel bundle of radius $r_0$ enters the converging lens. Where the rays enter the diverging lens, the bundle radius has shrunk to:", "options": ["$r_0'=\\frac{f_1-d}{f_1}r_0$", "$r_0=\\frac{f_1-d}{f_1}r_0'$", "$r_0'=\\frac{f_1-f_2}{f_1}r_0$", "$r_0'=r_0$"], "answer": 0, "hint": "Similar triangles towards the focus of $f_1$.", "solution": "The cone converges to $f_1$, so at distance d the radius is $r_0\\frac{f_1-d}{f_1}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q202", "kind": "practice"},
  {"id": "prac-sc-204", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "A zoom system: converging lens $f_1$, then a diverging lens $f_2=-|f_2|$ at distance d < $f_1$ with $|f_2|>f_1-d$. A parallel bundle of radius $r_0$ enters the converging lens. The effective focal length of the combination is:", "options": ["$\\frac{f_1|f_2|}{|f_2|-f_1+d}$", "$\\frac{f_1f_2}{f_1-f_2-d}$", "$\\frac{f_1}{f_2-f_1+d}$", "$\\frac{f_2}{f_1+f_2+d}$"], "answer": 0, "hint": "$\\frac1F=\\frac1{f_1}+\\frac1{f_2}-\\frac{d}{f_1f_2}$.", "solution": "With $f_2=-|f_2|$: $F=\\frac{f_1|f_2|}{|f_2|-f_1+d}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q204", "kind": "practice"},
  {"id": "prac-sc-208", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A ray goes from medium $\\mu_2$ into medium $\\mu_1$ at incidence $i=\\pi/3$. The plot shows |r − i| versus $k=\\mu_1/\\mu_2$ (r = refraction angle): constant $\\theta_1$ up to $k_1$, zero at $k_2$, then rising. The value of $k_1$ is:", "img": "figures/prac-sc-p70.png", "imgAlt": "Ray from μ2 into μ1 at angle i; graph of |r − i| vs k: flat at θ1 till k1, dips to zero at k2, then rises to θ2", "options": ["$\\frac2{\\sqrt3}$", "1", "$\\frac1{\\sqrt3}$", "$\\frac{\\sqrt3}2$"], "answer": 3, "hint": "$k_1$ marks the critical condition.", "solution": "$\\sin r=\\frac{\\sin i}{k}=1$ ⇒ $k=\\frac{\\sqrt3}{2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q208", "kind": "practice"},
  {"id": "prac-sc-209", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A ray goes from medium $\\mu_2$ into medium $\\mu_1$ at incidence $i=\\pi/3$. The plot shows |r − i| versus $k=\\mu_1/\\mu_2$ (r = refraction angle): constant $\\theta_1$ up to $k_1$, zero at $k_2$, then rising. The value of $\\theta_1$ is:", "img": "figures/prac-sc-p70.png", "imgAlt": "Ray from μ2 into μ1 at angle i; graph of |r − i| vs k: flat at θ1 till k1, dips to zero at k2, then rises to θ2", "options": ["π/3", "π/2", "π/6", "zero"], "answer": 2, "hint": "At the critical condition r = π/2.", "solution": "$|r-i|=\\frac\\pi2-\\frac\\pi3=\\frac\\pi6$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q209", "kind": "practice"},
  {"id": "prac-sc-210", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A ray goes from medium $\\mu_2$ into medium $\\mu_1$ at incidence $i=\\pi/3$. The plot shows |r − i| versus $k=\\mu_1/\\mu_2$ (r = refraction angle): constant $\\theta_1$ up to $k_1$, zero at $k_2$, then rising. The value of $k_2$ is:", "img": "figures/prac-sc-p70.png", "imgAlt": "Ray from μ2 into μ1 at angle i; graph of |r − i| vs k: flat at θ1 till k1, dips to zero at k2, then rises to θ2", "options": ["1", "2", "1/2", "none"], "answer": 0, "hint": "|r − i| = 0 ⇒ no bending.", "solution": "Equal indices ⇒ k = 1.", "source": "Sri Chaitanya · Total Physics Important Questions · Q210", "kind": "practice"},
  {"id": "prac-sc-214", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A thin concavo-convex glass lens (μ = 1.5) has convex radius 20 cm and concave radius 60 cm. Its convex side is silvered. The magnitude of the focal length of the combination is:", "options": ["8.6 cm", "7.5 cm", "1.5 cm", "15 cm"], "answer": 1, "hint": "$P=2P_{lens}+P_{mirror}$.", "solution": "$f_{lens}=60$ cm, $f_{mirror}=10$ cm ⇒ $P=\\frac2{60}+\\frac1{10}=\\frac{4}{30}$ ⇒ 7.5 cm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q214", "kind": "practice"},
  {"id": "prac-sc-215", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A thin concavo-convex glass lens (μ = 1.5) has convex radius 20 cm and concave radius 60 cm. Its convex side is silvered. The combination behaves like:", "options": ["a concave mirror", "a convex mirror", "a concave lens", "a convex lens"], "answer": 0, "hint": "Net power is converging and light returns.", "solution": "Positive power, reflecting ⇒ concave mirror.", "source": "Sri Chaitanya · Total Physics Important Questions · Q215", "kind": "practice"},
  {"id": "prac-sc-217", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 1, "q": "At the polarising (Brewster) angle, the angle between the reflected and refracted rays is:", "options": ["π/8", "π/6", "π/4", "π/2"], "answer": 3, "hint": "Brewster: $\\tan i_p=\\mu$.", "solution": "The reflected and refracted rays are perpendicular.", "source": "Sri Chaitanya · Total Physics Important Questions · Q217", "kind": "practice"},
  {"id": "prac-sc-218", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 2, "q": "In an EM wave, $\\vec E=2\\hat i+3\\hat j$ and $\\vec H=3\\hat i-2\\hat j$. The direction of propagation is along:", "options": ["$-13\\hat k$", "$-10\\hat j$", "$-6\\hat i+6\\hat k$", "$5\\hat i-4\\hat k$"], "answer": 0, "hint": "Propagation is along $\\vec E\\times\\vec H$.", "solution": "$(2,3,0)\\times(3,-2,0)=(0,0,-13)$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q218", "kind": "practice"},
  {"id": "prac-sc-219", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 3, "q": "An analyser examines two adjacent plane-polarised beams A and B with perpendicular planes of vibration. In one position B shows zero intensity; after rotating the analyser 30°, the two beams appear equally bright. Then $I_A/I_B$ is:", "options": ["$\\sqrt3$", "1/3", "$\\frac1{\\sqrt2}$", "$\\sqrt5$"], "answer": 1, "hint": "At first the analyser is parallel to A.", "solution": "$I_A\\cos^230°=I_B\\sin^230°$ ⇒ $\\frac{I_A}{I_B}=\\tan^230°=\\frac13$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q219", "kind": "practice"},
  {"id": "prac-sc-220", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 2, "q": "A point source of wavelength 6000 Å is at a very small height h above a flat mirror MN. The reflected light has 36% of the incident intensity. Fringes are seen on a screen parallel to the mirror at a large distance D. The fringes on the screen are:", "options": ["circles", "ellipses", "parabolas", "straight lines"], "answer": 0, "hint": "Source and its image lie on the normal to the screen.", "solution": "Equal path differences lie on circles centred on the foot of that normal.", "source": "Sri Chaitanya · Total Physics Important Questions · Q220", "kind": "practice"},
  {"id": "prac-sc-222", "exam": "JEE", "subject": "Physics", "chapter": "Wave Optics", "type": "mcq", "difficulty": 2, "q": "A point source of wavelength 6000 Å is at a very small height h above a flat mirror MN. The reflected light has 36% of the incident intensity. Fringes are seen on a screen parallel to the mirror at a large distance D. The ratio of maximum to minimum intensity at P is:", "options": ["2 : 1", "4 : 1", "8 : 1", "16 : 1"], "answer": 3, "hint": "Amplitude ratio 1 : 0.6.", "solution": "$\\left(\\frac{1.6}{0.4}\\right)^2=16$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q222", "kind": "practice"},
  {"id": "prac-sc-223", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 3, "q": "A uniform field B lies in the xy-plane at 45° to the x-axis. A rigid square frame PQRS (side L, each side of mass M) carrying current $I_0$ lies in the xy-plane with its centre at O and sides along the axes, as shown. The torque on the frame due to the field is:", "img": "figures/prac-sc-p75.png", "imgAlt": "Square frame PQRS centred at the origin in a uniform field at 45° to the x-axis", "options": ["$\\frac{I_0L^2B}{\\sqrt2}(\\hat i+\\hat j)$", "$\\frac{I_0L^2B}{\\sqrt2}(-\\hat i+\\hat j)$", "$\\frac{I_0L^2B}{2}(-\\hat i-\\hat j)$", "$\\frac{I_0L^2B}{2}(\\hat i+\\hat j)$"], "answer": 1, "hint": "$\\vec\\tau=\\vec m\\times\\vec B$ with $\\vec m=I_0L^2\\hat k$.", "solution": "$I_0L^2\\hat k\\times\\frac{B}{\\sqrt2}(\\hat i+\\hat j)=\\frac{I_0L^2B}{\\sqrt2}(\\hat j-\\hat i)$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q223", "kind": "practice"},
  {"id": "prac-sc-224", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 4, "q": "A uniform field B lies in the xy-plane at 45° to the x-axis. A rigid square frame PQRS (side L, each side of mass M) carrying current $I_0$ lies in the xy-plane with its centre at O and sides along the axes, as shown. The angle turned in a short time Δt is:", "img": "figures/prac-sc-p75.png", "imgAlt": "Square frame PQRS centred at the origin in a uniform field at 45° to the x-axis", "options": ["$\\frac{3I_0B}{4M}(\\Delta t)^2$", "$\\frac{4I_0B}{M}(\\Delta t)^2$", "$\\frac{2I_0B}{3M}(\\Delta t)^2$", "$\\frac{4I_0B}{3M}(\\Delta t)^2$"], "answer": 0, "hint": "I about a diagonal = half of I about the normal axis.", "solution": "$I=\\frac12\\cdot\\frac{4ML^2}{3}=\\frac{2ML^2}{3}$, $\\alpha=\\frac{3I_0B}{2M}$, θ = ½α(Δt)².", "source": "Sri Chaitanya · Total Physics Important Questions · Q224", "kind": "practice"},
  {"id": "prac-sc-225", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 2, "q": "A uniform field B lies in the xy-plane at 45° to the x-axis. A rigid square frame PQRS (side L, each side of mass M) carrying current $I_0$ lies in the xy-plane with its centre at O and sides along the axes, as shown. The frame tends to rotate about:", "img": "figures/prac-sc-p75.png", "imgAlt": "Square frame PQRS centred at the origin in a uniform field at 45° to the x-axis", "options": ["SQ", "PQ", "PS", "PR"], "answer": 0, "hint": "Axis is along the torque, $-\\hat i+\\hat j$.", "solution": "That's the diagonal from Q (+,−) to S (−,+).", "source": "Sri Chaitanya · Total Physics Important Questions · Q225", "kind": "practice"},
  {"id": "prac-sc-226", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 3, "q": "A coil of inductance L joins the ends of two horizontal zero-resistance rails a distance l apart in a uniform vertical field B. A conductor of mass m on the rails is given velocity $v_0$ at t = 0. During the motion, the conductor:", "options": ["slows down continuously", "comes to rest after some time", "comes to rest and then returns in the opposite direction", "keeps constant velocity"], "answer": 2, "hint": "$L\\frac{di}{dt}=Blv$ and $m\\frac{dv}{dt}=-Bli$ give SHM.", "solution": "The rod oscillates: it stops and comes back.", "source": "Sri Chaitanya · Total Physics Important Questions · Q226", "kind": "practice"},
  {"id": "prac-sc-227", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 3, "q": "A coil of inductance L joins the ends of two horizontal zero-resistance rails a distance l apart in a uniform vertical field B. A conductor of mass m on the rails is given velocity $v_0$ at t = 0. The motion of the conductor is:", "options": ["non-uniform, exponentially decreasing velocity", "non-uniform, sinusoidally varying velocity", "uniform", "none of these"], "answer": 1, "hint": "No resistance ⇒ no damping.", "solution": "$\\ddot v=-\\frac{B^2l^2}{mL}v$: sinusoidal.", "source": "Sri Chaitanya · Total Physics Important Questions · Q227", "kind": "practice"},
  {"id": "prac-sc-228", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 4, "q": "A coil of inductance L joins the ends of two horizontal zero-resistance rails a distance l apart in a uniform vertical field B. A conductor of mass m on the rails is given velocity $v_0$ at t = 0. The magnetic energy in the inductor is:", "options": ["maximum at t = 0", "maximum at $t=\\frac{2\\pi\\sqrt m}{Bl}$", "maximum at $t=\\frac{\\pi\\sqrt m}{Bl}$", "none of these"], "answer": 3, "hint": "It's maximum when v = 0, at a quarter period.", "solution": "$t=\\frac\\pi2\\frac{\\sqrt{mL}}{Bl}$: depends on L, so none of the listed times.", "source": "Sri Chaitanya · Total Physics Important Questions · Q228", "kind": "practice"},
  {"id": "prac-sc-229", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 2, "q": "A series LCR circuit is driven by $V=V_0\\sin\\omega t$, with $\\frac{1}{\\omega C}-\\omega L=R$. The voltage across R differs in phase from the source emf by:", "options": ["π/2", "0", "π/4", "π"], "answer": 2, "hint": "$\\tan\\phi=\\frac{X_C-X_L}{R}=1$.", "solution": "Current (and $V_R$) leads by π/4.", "source": "Sri Chaitanya · Total Physics Important Questions · Q229", "kind": "practice"},
  {"id": "prac-sc-230", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 3, "q": "A series LCR circuit is driven by $V=V_0\\sin\\omega t$, with $\\frac{1}{\\omega C}-\\omega L=R$. The rms voltage across the capacitor is:", "options": ["$\\frac{V_0}{\\sqrt2}$", "$V_0R\\omega C$", "zero", "$\\frac{V_0}{2R\\omega C}$"], "answer": 3, "hint": "$Z=\\sqrt2R$.", "solution": "$I_{rms}=\\frac{V_0}{2R}$ ⇒ $V_C=\\frac{V_0}{2R\\omega C}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q230", "kind": "practice"},
  {"id": "prac-sc-231", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 4, "q": "A series LCR circuit is driven by $V=V_0\\sin\\omega t$, with $\\frac{1}{\\omega C}-\\omega L=R$. The voltage across the inductor is:", "options": ["$\\frac{V_0\\omega L}{\\sqrt2R}\\sin\\left(\\omega t+\\frac{3\\pi}4\\right)$", "$\\frac{V_0\\omega L}{\\sqrt2R}\\sin\\omega t$", "$\\frac{V_0\\omega L}{\\sqrt2R}\\sin\\left(\\omega t+\\frac\\pi2\\right)$", "$\\frac{V_0\\omega L}{\\sqrt2R}\\cos\\omega t$"], "answer": 0, "hint": "Current leads by π/4; $V_L$ leads current by π/2.", "solution": "$I_0=\\frac{V_0}{\\sqrt2R}$ ⇒ $V_L=I_0\\omega L\\sin(\\omega t+\\frac{3\\pi}{4})$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q231", "kind": "practice"},
  {"id": "prac-sc-232", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 4, "q": "A solenoid (resistance R, inductance L) containing a soft-iron core is connected to a battery of emf E (no internal resistance). In steady state, the iron is pulled out suddenly so that the inductance falls to ηL. The work done to pull out the iron is:", "options": ["$\\frac{\\eta LE^2}{2R^2}$", "$\\frac{(1-\\eta)LE^2}{2R^2}$", "$\\frac{(1-\\eta)LE^2}{\\eta R^2}$", "$\\frac{(1-\\eta)LE^2}{2\\eta R^2}$"], "answer": 3, "hint": "Sudden change ⇒ flux LI conserved.", "solution": "Current jumps to $\\frac{I_0}{\\eta}$; energy rises from $\\frac12LI_0^2$ to $\\frac{LI_0^2}{2\\eta}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q232", "kind": "practice"},
  {"id": "prac-sc-233", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 4, "q": "A solenoid (resistance R, inductance L) containing a soft-iron core is connected to a battery of emf E (no internal resistance). In steady state, the iron is pulled out suddenly so that the inductance falls to ηL. With t = 0 at the instant the iron is removed and $\\lambda=\\frac{\\eta L}{R}$, the current is:", "options": ["$\\frac ER\\left[1-\\left(1-\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac ER\\left[1+\\left(1+\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac ER\\left[1-\\left(1+\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac ER\\left[1+\\left(1-\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$"], "answer": 0, "hint": "Starts at $\\frac{E}{\\eta R}$, relaxes to $\\frac ER$.", "solution": "$i=\\frac ER+\\left(\\frac{E}{\\eta R}-\\frac ER\\right)e^{-t/\\lambda}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q233", "kind": "practice"},
  {"id": "prac-sc-234", "exam": "JEE", "subject": "Physics", "chapter": "Electromagnetic Induction", "type": "mcq", "difficulty": 3, "q": "A solenoid (resistance R, inductance L) containing a soft-iron core is connected to a battery of emf E (no internal resistance). In steady state, the iron is pulled out suddenly so that the inductance falls to ηL. The power supplied by the battery is:", "options": ["$\\frac{E^2}R\\left[1-\\left(1-\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac{E^2}R\\left[1+\\left(1+\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac{E^2}R\\left[1-\\left(1+\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$", "$\\frac{E^2}R\\left[1+\\left(1-\\frac1\\eta\\right)e^{-t/\\lambda}\\right]$"], "answer": 0, "hint": "P = Ei.", "solution": "Multiply the current by E.", "source": "Sri Chaitanya · Total Physics Important Questions · Q234", "kind": "practice"},
  {"id": "prac-sc-236", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 2, "q": "A flux density of 1.2 Wb/m² is needed in the 2 mm air gap of an electromagnet. The mmf required for the gap is about:", "options": ["1910 AT", "910 AT", "1500 AT", "1200 AT"], "answer": 0, "hint": "mmf = $\\frac{Bl}{\\mu_0}$.", "solution": "$\\frac{1.2\\times2\\times10^{-3}}{4\\pi\\times10^{-7}}\\approx1910$ AT.", "source": "Sri Chaitanya · Total Physics Important Questions · Q236", "kind": "practice"},
  {"id": "prac-sc-237", "exam": "JEE", "subject": "Physics", "chapter": "Magnetic Effects of Current", "type": "mcq", "difficulty": 1, "q": "An iron ring of volume 960 cm³ and mean circumference 80 cm carries a flux of 1.2 mWb. The flux density in the ring is:", "options": ["1 Wb/m²", "0.1 Wb/m²", "2 Wb/m²", "0.2 Wb/m²"], "answer": 0, "hint": "Area = volume / circumference.", "solution": "A = 12 cm² ⇒ B = 1.2×10⁻³/12×10⁻⁴ = 1 Wb/m².", "source": "Sri Chaitanya · Total Physics Important Questions · Q237", "kind": "practice"},
  {"id": "prac-sc-238", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 1, "q": "A coil of resistance 50.0 Ω and inductance 0.5 H is connected to a 110 V, 50 Hz source. The impedance of the coil is about:", "options": ["165 Ω", "55 Ω", "330 Ω", "none"], "answer": 0, "hint": "$X_L=2\\pi fL$.", "solution": "$X_L=157$ Ω ⇒ $Z=\\sqrt{50^2+157^2}\\approx165$ Ω.", "source": "Sri Chaitanya · Total Physics Important Questions · Q238", "kind": "practice"},
  {"id": "prac-sc-239", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 1, "q": "A coil of resistance 50.0 Ω and inductance 0.5 H is connected to a 110 V, 50 Hz source. The rms current is:", "options": ["1.5 A", "0.67 A", "1 A", "3 A"], "answer": 1, "hint": "I = V/Z.", "solution": "110/165 ≈ 0.67 A.", "source": "Sri Chaitanya · Total Physics Important Questions · Q239", "kind": "practice"},
  {"id": "prac-sc-240", "exam": "JEE", "subject": "Physics", "chapter": "Alternating Current", "type": "mcq", "difficulty": 1, "q": "A coil of resistance 50.0 Ω and inductance 0.5 H is connected to a 110 V, 50 Hz source. If the frequency is halved, the rms current:", "options": ["increases", "decreases", "stays unchanged", "depends on the phase"], "answer": 0, "hint": "$X_L\\propto f$.", "solution": "Lower reactance ⇒ lower Z ⇒ more current.", "source": "Sri Chaitanya · Total Physics Important Questions · Q240", "kind": "practice"},
  {"id": "prac-sc-247", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "Fusion occurs in two stages: (A) D + D → T + p; (B) T + D → ⁴He + n. Atomic masses (u): D 2.014102, T 3.016049, ⁴He 4.002603, ¹H 1.007825, n 1.008665. (1 u = 931.5 MeV) The energy released in the first stage is:", "options": ["4.033 MeV", "17.587 MeV", "40.33 MeV", "1.7587 MeV"], "answer": 0, "hint": "Q = (mass in − mass out) × 931.5.", "solution": "Δm = 4.028204 − 4.023874 = 0.00433 u ⇒ 4.03 MeV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q247", "kind": "practice"},
  {"id": "prac-sc-248", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "Fusion occurs in two stages: (A) D + D → T + p; (B) T + D → ⁴He + n. Atomic masses (u): D 2.014102, T 3.016049, ⁴He 4.002603, ¹H 1.007825, n 1.008665. (1 u = 931.5 MeV) The energy released in the second stage is:", "options": ["4.033 MeV", "17.587 MeV", "40.33 MeV", "1.7587 MeV"], "answer": 1, "hint": "T + D → He + n.", "solution": "Δm = 5.030151 − 5.011268 = 0.018883 u ⇒ 17.59 MeV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q248", "kind": "practice"},
  {"id": "prac-sc-249", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 3, "q": "Fusion occurs in two stages: (A) D + D → T + p; (B) T + D → ⁴He + n. Atomic masses (u): D 2.014102, T 3.016049, ⁴He 4.002603, ¹H 1.007825, n 1.008665. (1 u = 931.5 MeV) What percentage of the mass energy of the three deuterons used is released?", "options": ["0.184%", "0.284%", "0.384%", "0.484%"], "answer": 2, "hint": "Total release ≈ 21.62 MeV.", "solution": "3 × 2.014102 × 931.5 ≈ 5628 MeV ⇒ 21.62/5628 ≈ 0.384%.", "source": "Sri Chaitanya · Total Physics Important Questions · Q249", "kind": "practice"},
  {"id": "prac-sc-251", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 1, "q": "Light of wavelength 365 nm and intensity $10^{-8}$ W/m² falls on a surface with absorption coefficient 0.8 and work function 1.6 eV. The power absorbed per m² is:", "options": ["$6\\times10^{-9}$ W/m²", "$7\\times10^{-8}$ W/m²", "$8\\times10^{-9}$ W/m²", "$9\\times10^{-9}$ W/m²"], "answer": 2, "hint": "Absorbed = 0.8 × incident.", "solution": "$8\\times10^{-9}$ W/m².", "source": "Sri Chaitanya · Total Physics Important Questions · Q251", "kind": "practice"},
  {"id": "prac-sc-252", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 1, "q": "Light of wavelength 365 nm and intensity $10^{-8}$ W/m² falls on a surface with absorption coefficient 0.8 and work function 1.6 eV. The maximum KE of the photoelectrons is:", "options": ["1.8 eV", "2.8 eV", "3.8 eV", "4.8 eV"], "answer": 0, "hint": "E(eV) ≈ 1240/λ(nm).", "solution": "3.4 − 1.6 = 1.8 eV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q252", "kind": "practice"},
  {"id": "prac-sc-253", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 3, "q": "In β⁻ decay, $X\\to Y^*+\\beta^-+\\Delta E_1$ and $Y^*\\to Y+\\gamma+\\Delta E_2$. $M_X$, $M_Y$ are atomic masses. The mass defect of the decay is:", "options": ["$M_X-M_Y-m_e$", "$M_X-M_Y-2m_e$", "$M_X-M_Y$", "none of these"], "answer": 2, "hint": "Atomic masses already include the electrons.", "solution": "For β⁻ with atomic masses, electron masses cancel: $M_X-M_Y$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q253", "kind": "practice"},
  {"id": "prac-sc-254", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 3, "q": "In β⁻ decay, $X\\to Y^*+\\beta^-+\\Delta E_1$ and $Y^*\\to Y+\\gamma+\\Delta E_2$. $M_X$, $M_Y$ are atomic masses. The energy $\\Delta E_1$ released in the first step is:", "options": ["$=\\Delta mc^2$", "$<\\Delta mc^2$", "$>\\Delta mc^2$", "none"], "answer": 1, "hint": "Part of the total goes into the γ-ray later.", "solution": "$\\Delta mc^2=\\Delta E_1+\\Delta E_2$ ⇒ $\\Delta E_1<\\Delta mc^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q254", "kind": "practice"},
  {"id": "prac-sc-259", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 3, "q": "A point source of power $3.2\\times10^{-3}$ W emits 5 eV photons. It is 0.8 m from the centre of an isolated, initially neutral metal sphere (work function 3 eV, radius $8\\times10^{-3}$ m). One photoelectron is emitted per $10^6$ incident photons, and electrons are swept away at once. The number of photoelectrons emitted per second is:", "options": ["$10^5$", "$10^3$", "$10^7$", "$10^6$"], "answer": 0, "hint": "Fraction of photons hitting the sphere = $\\frac{r^2}{4d^2}$.", "solution": "$4\\times10^{15}$ photons/s × $2.5\\times10^{-5}$ = $10^{11}$ ⇒ $10^5$ electrons/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q259", "kind": "practice"},
  {"id": "prac-sc-260", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 4, "q": "A point source of power $3.2\\times10^{-3}$ W emits 5 eV photons. It is 0.8 m from the centre of an isolated, initially neutral metal sphere (work function 3 eV, radius $8\\times10^{-3}$ m). One photoelectron is emitted per $10^6$ incident photons, and electrons are swept away at once. The ratio of the incident wavelength to the de Broglie wavelength of the fastest photoelectrons is about:", "options": ["285.1", "255.3", "265.3", "none"], "answer": 0, "hint": "$K_{max}=2$ eV; $\\lambda_e=\\frac{1.227}{\\sqrt{K}}$ nm.", "solution": "248 nm / 0.868 nm ≈ 285.", "source": "Sri Chaitanya · Total Physics Important Questions · Q260", "kind": "practice"},
  {"id": "prac-sc-261", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 4, "q": "A point source of power $3.2\\times10^{-3}$ W emits 5 eV photons. It is 0.8 m from the centre of an isolated, initially neutral metal sphere (work function 3 eV, radius $8\\times10^{-3}$ m). One photoelectron is emitted per $10^6$ incident photons, and electrons are swept away at once. After what time does photoemission stop?", "options": ["105 s", "111 s", "150 s", "none"], "answer": 1, "hint": "Emission stops when the sphere's potential reaches 2 V.", "solution": "$Q=\\frac{2r}{k}=1.78\\times10^{-12}$ C = $1.11\\times10^7$ e ⇒ 111 s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q261", "kind": "practice"},
  {"id": "prac-sc-262", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "A radionuclide with decay constant λ is produced in a reactor at a rate $q_0t$ per second from t = 0. Each decay releases energy $E_0$. The differential equation for N is:", "options": ["$\\frac{dN}{dt}+\\lambda N=q_0t$", "$\\frac{dN}{dt}-\\lambda N=q_0t$", "$\\frac{dN}{dt}+q_0t=\\lambda N$", "$\\frac{dN}{dt}+q_0t=-\\lambda N$"], "answer": 0, "hint": "Rate = production − decay.", "solution": "$\\frac{dN}{dt}=q_0t-\\lambda N$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q262", "kind": "practice"},
  {"id": "prac-sc-263", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 4, "q": "A radionuclide with decay constant λ is produced in a reactor at a rate $q_0t$ per second from t = 0. Each decay releases energy $E_0$. The instantaneous power at time t is:", "options": ["$\\left(q_0t-\\frac{q_0}\\lambda+\\frac{q_0}\\lambda e^{-\\lambda t}\\right)E_0$", "$\\left(q_0t+\\frac{q_0}\\lambda-\\frac{q_0}\\lambda e^{-\\lambda t}\\right)E_0$", "$\\left(q_0t+\\frac{q_0}\\lambda+\\frac{q_0}\\lambda e^{-\\lambda t}\\right)E_0$", "$\\left(q_0t-\\frac{q_0}\\lambda-\\frac{q_0}\\lambda e^{-\\lambda t}\\right)E_0$"], "answer": 0, "hint": "Solve with N(0) = 0, then P = λN E₀.", "solution": "$N=\\frac{q_0t}{\\lambda}-\\frac{q_0}{\\lambda^2}(1-e^{-\\lambda t})$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q263", "kind": "practice"},
  {"id": "prac-sc-264", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 5, "q": "A radionuclide with decay constant λ is produced in a reactor at a rate $q_0t$ per second from t = 0. Each decay releases energy $E_0$. The average power over time t is:", "options": ["$\\left(\\frac{q_0t}2-\\frac{q_0}\\lambda+\\frac{q_0}{\\lambda^2t}-\\frac{q_0}{\\lambda^2t}e^{-\\lambda t}\\right)E_0$", "$\\left(\\frac{q_0t}2+\\frac{q_0}\\lambda+\\frac{q_0}{\\lambda^2t}-\\frac{q_0}{\\lambda^2t}e^{-\\lambda t}\\right)E_0$", "$\\left(\\frac{q_0t}2-\\frac{q_0}\\lambda+\\frac{q_0}{\\lambda^2t}+\\frac{q_0}{\\lambda^2t}e^{-\\lambda t}\\right)E_0$", "$\\left(\\frac{q_0t}2+\\frac{q_0}\\lambda+\\frac{q_0}{\\lambda^2t}+\\frac{q_0}{\\lambda^2t}e^{-\\lambda t}\\right)E_0$"], "answer": 0, "hint": "Integrate P from 0 to t and divide by t.", "solution": "$\\frac1t\\int_0^tP\\,dt$ gives (A).", "source": "Sri Chaitanya · Total Physics Important Questions · Q264", "kind": "practice"},
  {"id": "prac-sc-265", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 4, "q": "Two parallel metal plates A and B (area $5\\times10^{-4}$ m² each, 1 cm apart). B carries $+33.7\\times10^{-12}$ C. From t = 0, $10^{16}$ photons of 5 eV per m² per second fall on A (work function 2 eV); one photoelectron per $10^6$ photons, all collected by B. The KE of the most energetic photoelectron emitted at t = 10 s when it reaches B is:", "options": ["3 eV", "20 eV", "23 eV", "17 eV"], "answer": 2, "hint": "Find the charges at 10 s and the field between the plates.", "solution": "A: +8 pC, B: 25.7 pC ⇒ E = 2000 V/m accelerating electrons ⇒ 3 + 20 = 23 eV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q265", "kind": "practice"},
  {"id": "prac-sc-266", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 2, "q": "Two parallel metal plates A and B (area $5\\times10^{-4}$ m² each, 1 cm apart). B carries $+33.7\\times10^{-12}$ C. From t = 0, $10^{16}$ photons of 5 eV per m² per second fall on A (work function 2 eV); one photoelectron per $10^6$ photons, all collected by B. The number of photoelectrons emitted in 10 s is:", "options": ["$5\\times10^7$", "$2\\times10^6$", "$5\\times10^6$", "$2\\times10^7$"], "answer": 0, "hint": "Photons on A per second = $10^{16}\\times5\\times10^{-4}$.", "solution": "$5\\times10^{12}\\times10^{-6}\\times10=5\\times10^7$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q266", "kind": "practice"},
  {"id": "prac-sc-267", "exam": "JEE", "subject": "Physics", "chapter": "Dual Nature of Matter", "type": "mcq", "difficulty": 4, "q": "Two parallel metal plates A and B (area $5\\times10^{-4}$ m² each, 1 cm apart). B carries $+33.7\\times10^{-12}$ C. From t = 0, $10^{16}$ photons of 5 eV per m² per second fall on A (work function 2 eV); one photoelectron per $10^6$ photons, all collected by B. The electric field between A and B at t = 10 s is:", "options": ["1000 V/m", "2000 V/m", "1500 V/m", "2500 V/m"], "answer": 1, "hint": "$E=\\frac{|q_B-q_A|}{2\\varepsilon_0A}$.", "solution": "$\\frac{17.7\\times10^{-12}}{2\\times8.85\\times10^{-12}\\times5\\times10^{-4}}=2000$ V/m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q267", "kind": "practice"},
  {"id": "prac-sc-268", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "In which equation does X represent a β⁺ particle?", "options": ["$^{14}_6C\\to{}^{14}_7N+X+\\bar\\nu$", "$^{64}_{29}Cu\\to{}^{64}_{28}Ni+X+\\nu$", "$^{64}_{29}Cu+\\beta^-\\to{}^{64}_{28}Ni+X$", "$^{238}_{92}U\\to{}^{234}_{90}Th+X$"], "answer": 1, "hint": "β⁺ lowers Z by 1 and comes with a neutrino.", "solution": "Cu (29) → Ni (28) + e⁺ + ν.", "source": "Sri Chaitanya · Total Physics Important Questions · Q268", "kind": "practice"},
  {"id": "prac-sc-269", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "Which decay is accompanied by X-rays?", "options": ["β-decay", "positron emission", "electron capture", "gamma decay"], "answer": 2, "hint": "A vacancy is left in an inner shell.", "solution": "After K-capture, outer electrons fill the hole and emit X-rays.", "source": "Sri Chaitanya · Total Physics Important Questions · Q269", "kind": "practice"},
  {"id": "prac-sc-270", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 2, "q": "Choose the correct statement about β-decay:", "options": ["The electron energy varies from zero to a maximum for a given nuclide", "The electron and recoiling nucleus always move exactly opposite", "The end-point energy exceeds the mass-difference energy", "The neutrino hypothesis violates angular momentum conservation"], "answer": 0, "hint": "Three bodies share the energy.", "solution": "Because the (anti)neutrino takes a variable share, β energies form a continuous spectrum.", "source": "Sri Chaitanya · Total Physics Important Questions · Q270", "kind": "practice"},
  {"id": "prac-sc-271", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 3, "q": "Nuclei A and B both decay to stable C. A emits two α and three β⁻ particles; B emits one α and five β⁻. At t = 0 there are $4N_0$ of A and $N_0$ of B; half-lives are 1 min (A) and 2 min (B). If $Z_1,A_1$ and $Z_2,A_2$ are the atomic and mass numbers of A and B:", "options": ["$Z_1-Z_2=6$", "$A_1-A_2=4$", "both (A) and (B)", "neither"], "answer": 1, "hint": "α: A −4, Z −2; β⁻: Z +1.", "solution": "$A_1=A_C+8$, $A_2=A_C+4$ ⇒ 4. $Z_1-Z_2=1-(-3)=4$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q271", "kind": "practice"},
  {"id": "prac-sc-272", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 4, "q": "Nuclei A and B both decay to stable C. A emits two α and three β⁻ particles; B emits one α and five β⁻. At t = 0 there are $4N_0$ of A and $N_0$ of B; half-lives are 1 min (A) and 2 min (B). The number of C nuclei when the numbers of A and B are equal is:", "options": ["$2N_0$", "$3N_0$", "$\\frac{9N_0}{2}$", "$\\frac{5N_0}{2}$"], "answer": 2, "hint": "$4N_02^{-t}=N_02^{-t/2}$.", "solution": "t = 4 min, each = N₀/4 ⇒ C = 5N₀ − N₀/2 = 9N₀/2.", "source": "Sri Chaitanya · Total Physics Important Questions · Q272", "kind": "practice"},
  {"id": "prac-sc-273", "exam": "JEE", "subject": "Physics", "chapter": "Nuclei", "type": "mcq", "difficulty": 4, "q": "Nuclei A and B both decay to stable C. A emits two α and three β⁻ particles; B emits one α and five β⁻. At t = 0 there are $4N_0$ of A and $N_0$ of B; half-lives are 1 min (A) and 2 min (B). At what time are the disintegration rates of A and B equal?", "options": ["4 min", "6 min", "8 min", "2 min"], "answer": 1, "hint": "$\\lambda_A=2\\lambda_B$.", "solution": "$2\\cdot4\\cdot2^{-t}=2^{-t/2}$ ⇒ $2^{t/2}=8$ ⇒ t = 6 min.", "source": "Sri Chaitanya · Total Physics Important Questions · Q273", "kind": "practice"},
  {"id": "prac-sc-274", "exam": "JEE", "subject": "Physics", "chapter": "Thermal Properties of Matter", "type": "mcq", "difficulty": 3, "q": "A space station is a black sphere kept at 500 K by its appliances. It is then enclosed by a thin black spherical screen of nearly the same radius. Outer space is at 0 K. The temperature of the screen is:", "options": ["< 500 K", "= 500 K", "> 500 K", "none"], "answer": 1, "hint": "The appliances' power is unchanged; the screen radiates it outward.", "solution": "$\\sigma AT_s^4=\\sigma A(500)^4$ ⇒ 500 K.", "source": "Sri Chaitanya · Total Physics Important Questions · Q274", "kind": "practice"},
  {"id": "prac-sc-275", "exam": "JEE", "subject": "Physics", "chapter": "Thermal Properties of Matter", "type": "mcq", "difficulty": 3, "q": "A space station is a black sphere kept at 500 K by its appliances. It is then enclosed by a thin black spherical screen of nearly the same radius. Outer space is at 0 K. The new temperature of the station shell is:", "options": ["< 500 K", "= 500 K", "> 500 K", "none"], "answer": 2, "hint": "The shell now receives radiation back from the screen.", "solution": "$T^4-T_s^4=500^4$ ⇒ $T=2^{1/4}\\times500>500$ K.", "source": "Sri Chaitanya · Total Physics Important Questions · Q275", "kind": "practice"},
  {"id": "prac-sc-276", "exam": "JEE", "subject": "Physics", "chapter": "Thermal Properties of Matter", "type": "mcq", "difficulty": 2, "q": "A space station is a black sphere kept at 500 K by its appliances. It is then enclosed by a thin black spherical screen of nearly the same radius. Outer space is at 0 K. The net heat radiated by the station shell is:", "options": ["less than earlier", "same as earlier", "more than earlier", "none"], "answer": 1, "hint": "Steady state: net output = appliance power.", "solution": "Unchanged.", "source": "Sri Chaitanya · Total Physics Important Questions · Q276", "kind": "practice"},
  {"id": "prac-sc-278", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 4, "q": "A disc of radius 10 cm rotates in the XY-plane about its centre. Point A, with OA at 53° above the x-axis, has acceleration $\\vec a_A=-6\\hat i$ m/s². The angular acceleration of the disc is:", "img": "figures/prac-sc-p93.png", "imgAlt": "Disc with OA at 53° above the x-axis and OB at 37° below it", "options": ["48 rad/s² anticlockwise", "12 rad/s² anticlockwise", "48 rad/s² clockwise", "12 rad/s² clockwise"], "answer": 0, "hint": "Split $\\vec a_A$ into radial ($\\omega^2r$) and tangential ($\\alpha r$) parts.", "solution": "The y-component gives α = 4ω²/3, the x-component ω² = 36 ⇒ α = 48 rad/s², anticlockwise.", "source": "Sri Chaitanya · Total Physics Important Questions · Q278", "kind": "practice"},
  {"id": "prac-sc-280", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 4, "q": "A square frame of four rods (length l, mass m each) is hinged at corner A about a horizontal axis parallel to diagonal DB, with C vertically above A. It is slightly disturbed and swings down until C is at its lowest point. The angular velocity of the frame when inverted is:", "options": ["$\\sqrt{\\frac{3\\sqrt2g}{l}}$", "$\\sqrt{\\frac{3g}{l}}$", "$\\sqrt{\\frac{3g}{\\sqrt2l}}$", "$\\sqrt{\\frac{6g}{l}}$"], "answer": 0, "hint": "COM falls $\\sqrt2l$; I about the hinge axis = $\\frac{8ml^2}{3}$.", "solution": "$4mg\\sqrt2l=\\frac12\\cdot\\frac{8ml^2}{3}\\omega^2$ ⇒ $\\omega^2=\\frac{3\\sqrt2g}{l}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q280", "kind": "practice"},
  {"id": "prac-sc-281", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 4, "q": "A square frame of four rods (length l, mass m each) is hinged at corner A about a horizontal axis parallel to diagonal DB, with C vertically above A. It is slightly disturbed and swings down until C is at its lowest point. The speed of point B then is:", "options": ["$\\sqrt{\\frac{3}{\\sqrt2}gl}$", "$\\sqrt{3\\sqrt2gl}$", "$\\sqrt{\\frac{3g}{l}}$", "$\\sqrt{\\frac{6g}{l}}$"], "answer": 0, "hint": "B is $\\frac{l}{\\sqrt2}$ from the axis.", "solution": "$v=\\omega\\frac{l}{\\sqrt2}$ ⇒ $v^2=\\frac{3}{\\sqrt2}gl$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q281", "kind": "practice"},
  {"id": "prac-sc-283", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A disc of mass M lies on a frictionless floor. A small ball of mass M moving at velocity V strikes it; the line of impact (through the disc's centre) makes angle θ with V. Coefficient of restitution e. The velocity of approach (ball + disc) is:", "options": ["$V\\cos\\theta$", "$V\\sin\\theta$", "V", "zero"], "answer": 0, "hint": "Only the component along the line of impact counts.", "solution": "$V\\cos\\theta$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q283", "kind": "practice"},
  {"id": "prac-sc-284", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A disc of mass M lies on a frictionless floor. A small ball of mass M moving at velocity V strikes it; the line of impact (through the disc's centre) makes angle θ with V. Coefficient of restitution e. The velocity of the disc after collision is:", "options": ["$\\frac{V\\cos\\theta}2$", "$\\frac{eV\\cos\\theta}2$", "$\\frac{V\\cos\\theta(1+e)}2$", "$\\frac{V\\cos\\theta(1-e)}2$"], "answer": 2, "hint": "Equal masses, along the line of impact.", "solution": "Momentum + restitution ⇒ $\\frac{(1+e)V\\cos\\theta}{2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q284", "kind": "practice"},
  {"id": "prac-sc-285", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A disc of mass M lies on a frictionless floor. A small ball of mass M moving at velocity V strikes it; the line of impact (through the disc's centre) makes angle θ with V. Coefficient of restitution e. The speed of the ball after collision is:", "options": ["$eV\\cos\\theta$", "$V\\sqrt{\\frac{\\cos^2\\theta(1-e)^2}{4}+\\sin^2\\theta}$", "$V\\sqrt{\\cos^2\\theta(1+e)^2+\\frac{\\sin^2\\theta}4}$", "$V\\sqrt{\\frac{\\cos^2\\theta(1+e)^2}{4}+\\sin^2\\theta}$"], "answer": 1, "hint": "The perpendicular component is unchanged.", "solution": "Along the line: $\\frac{(1-e)V\\cos\\theta}{2}$; perpendicular: $V\\sin\\theta$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q285", "kind": "practice"},
  {"id": "prac-sc-289", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 1, "q": "A main speaker (8.00 Ω) and a remote speaker (4.00 Ω) are connected in parallel to a music system. At an instant the voltage across them is 6.00 V. The equivalent resistance of the speakers is:", "options": ["12 Ω", "4 Ω", "2.67 Ω", "0.375 Ω"], "answer": 2, "hint": "Parallel.", "solution": "$\\frac{8\\times4}{12}=2.67$ Ω.", "source": "Sri Chaitanya · Total Physics Important Questions · Q289", "kind": "practice"},
  {"id": "prac-sc-290", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 1, "q": "A main speaker (8.00 Ω) and a remote speaker (4.00 Ω) are connected in parallel to a music system. At an instant the voltage across them is 6.00 V. The total current supplied is:", "options": ["2.25 A", "1 A", "16 A", "1.5 A"], "answer": 0, "hint": "I = V/R.", "solution": "6/2.67 = 2.25 A.", "source": "Sri Chaitanya · Total Physics Important Questions · Q290", "kind": "practice"},
  {"id": "prac-sc-291", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 1, "q": "A main speaker (8.00 Ω) and a remote speaker (4.00 Ω) are connected in parallel to a music system. At an instant the voltage across them is 6.00 V. The power in the 4.00 Ω speaker is:", "options": ["9 W", "4.5 W", "13.5 W", "0"], "answer": 0, "hint": "$V^2/R$.", "solution": "36/4 = 9 W.", "source": "Sri Chaitanya · Total Physics Important Questions · Q291", "kind": "practice"},
  {"id": "prac-sc-292", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 3, "q": "In the circuit shown the ammeter reads 2 A. XY is either a resistor or a battery. If XY is a resistor, its value is:", "img": "figures/prac-sc-p98.png", "imgAlt": "Series loop: 40 V (2 Ω) and opposing 8 V (2 Ω) cells, 3 Ω, 6 Ω ∥ 12 Ω, ammeter, element XY; 2 A flows", "options": ["5 Ω", "9 Ω", "13 Ω", "9.75 Ω"], "answer": 0, "hint": "Net emf 40 − 8 = 32 V drives 2 A.", "solution": "Other resistances total 2 + 2 + 3 + 4 = 11 Ω ⇒ 32 − 22 = 10 V across XY ⇒ 5 Ω.", "source": "Sri Chaitanya · Total Physics Important Questions · Q292", "kind": "practice"},
  {"id": "prac-sc-293", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 3, "q": "In the circuit shown the ammeter reads 2 A. XY is either a resistor or a battery. If XY is a battery with internal resistance 2 Ω that is being charged, its emf is:", "img": "figures/prac-sc-p98.png", "imgAlt": "Series loop: 40 V (2 Ω) and opposing 8 V (2 Ω) cells, 3 Ω, 6 Ω ∥ 12 Ω, ammeter, element XY; 2 A flows", "options": ["6 V", "−6 V", "0", "2 V"], "answer": 0, "hint": "Terminal voltage 10 V = emf + Ir.", "solution": "10 = e + 2×2 ⇒ 6 V.", "source": "Sri Chaitanya · Total Physics Important Questions · Q293", "kind": "practice"},
  {"id": "prac-sc-294", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 3, "q": "In the circuit shown the ammeter reads 2 A. XY is either a resistor or a battery. Treating XY as that battery, the potential change going from Y to X ($V_X-V_Y$) is:", "img": "figures/prac-sc-p98.png", "imgAlt": "Series loop: 40 V (2 Ω) and opposing 8 V (2 Ω) cells, 3 Ω, 6 Ω ∥ 12 Ω, ammeter, element XY; 2 A flows", "options": ["−10 V", "10 V", "0", "2 V"], "answer": 0, "hint": "Current flows through XY from Y to X.", "solution": "Potential drops by 10 V in the direction of current ⇒ $V_X-V_Y=-10$ V.", "source": "Sri Chaitanya · Total Physics Important Questions · Q294", "kind": "practice"},
  {"id": "prac-sc-298", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 2, "q": "A potentiometer wire AB (1 m) is driven by a 2 V cell (internal resistance 0.4 Ω). A standard cell of 1.02 V balances at 66.3 cm; an unknown cell e balances at 82.3 cm. The value of e is:", "options": ["1.26 V", "2.63 V", "1.83 V", "none"], "answer": 0, "hint": "e ∝ balancing length.", "solution": "$1.02\\times\\frac{82.3}{66.3}=1.266$ V.", "source": "Sri Chaitanya · Total Physics Important Questions · Q298", "kind": "practice"},
  {"id": "prac-sc-299", "exam": "JEE", "subject": "Physics", "chapter": "Current Electricity", "type": "mcq", "difficulty": 2, "q": "A potentiometer wire AB (1 m) is driven by a 2 V cell (internal resistance 0.4 Ω). A standard cell of 1.02 V balances at 66.3 cm; an unknown cell e balances at 82.3 cm. If a 4 V battery replaces e, the balancing length is:", "options": ["88.3 cm", "47.3 cm", "95 cm", "cannot be found"], "answer": 3, "hint": "The whole wire has less than 2 V across it.", "solution": "4 V exceeds the potential across the wire: no balance point.", "source": "Sri Chaitanya · Total Physics Important Questions · Q299", "kind": "practice"},
  {"id": "prac-allen26-1", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A far-sighted person's least distance of distinct vision is 1 m. The power of the spectacle lens that reduces it to 25 cm is:", "options": ["+3 D", "+2 D", "−3 D", "None"], "answer": 0, "hint": "The lens must image an object at 25 cm to 100 cm (same side).", "solution": "$\\frac1f=\\frac1{-100}-\\frac1{-25}=\\frac{3}{100}$ ⇒ +3 D.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q1", "kind": "practice"},
  {"id": "prac-allen26-2", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A telescope in normal adjustment has tube length 100 cm and magnifying power 9. An old man cannot see beyond 90 cm. To use it, he must reduce the tube length by:", "options": ["1.5 cm", "0.5 cm", "1 cm", "2 cm"], "answer": 2, "hint": "$f_o=90$, $f_e=10$; the final image must be 90 cm from the eyepiece.", "solution": "Eyepiece object: $-\\frac1{90}-\\frac1u=\\frac1{10}$ ⇒ u = −9 cm ⇒ tube 99 cm ⇒ 1 cm shorter.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q2", "kind": "practice"},
  {"id": "prac-allen26-3", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "An astronomical telescope has magnifying power 6 for distant objects and separation 42 cm with the final image at infinity. The focal lengths (cm) of objective and eyepiece are:", "options": ["$f_o=36, f_e=6$", "$f_o=50, f_e=8$", "$f_o=20, f_e=10$", "$f_o=40, f_e=8$"], "answer": 0, "hint": "$f_o/f_e=6$, $f_o+f_e=42$.", "solution": "36 and 6.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q3", "kind": "practice"},
  {"id": "prac-allen26-4", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "A telescope has objective focal length 100 cm and eyepiece 2.5 cm. Looking into the objective (the wrong end), distant objects look smaller. By what factor is the angular size reduced?", "options": ["40", "10", "20", "4"], "answer": 0, "hint": "The roles of the lenses swap.", "solution": "Factor $f_o/f_e=40$.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q4", "kind": "practice"},
  {"id": "prac-allen26-5", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "A microscope's objective and eyepiece have powers 100 D and 20 D. With a relaxed eye its angular magnification is 50. If the lens separation is increased by 2.0 cm (eye still relaxed), the magnification becomes:", "options": ["60", "40", "72", "20"], "answer": 0, "hint": "Eyepiece magnification 25/5 = 5 stays; the objective's image moves out 2 cm.", "solution": "$m_o=10$ ⇒ image at 11 cm; now at 13 cm ⇒ $m_o=12$ ⇒ 60.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q5", "kind": "practice"},
  {"id": "prac-allen26-6", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A distant balloon subtends 0.25° at the objective of a telescope; its image subtends 1.5°. The tube is 35 cm long. The focal length of the eyepiece is:", "options": ["10 cm", "3 cm", "5 cm", "7 cm"], "answer": 2, "hint": "M = 6 and $f_o+f_e=35$.", "solution": "$f_e=5$ cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q6", "kind": "practice"},
  {"id": "prac-allen26-8", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A telescope increases the intensity (brightness per unit angle) of light by a factor $\\eta=4.0\\times10^4$. If the image of a distant object subtends 2.0°, the object itself subtends:", "options": ["0.6′", "0.7′", "0.4′", "1.2′"], "answer": 0, "hint": "Intensity gain = M², so M = √η = 200.", "solution": "2°/200 = 0.01° = 0.6′.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q8", "kind": "practice"},
  {"id": "prac-allen26-9", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A compound microscope has objective f = 2 cm and eyepiece f = 6.25 cm, 15 cm apart. For the final image at the least distance of distinct vision (25 cm), the object must be how far from the objective?", "options": ["2.5 cm", "2 cm", "3 cm", "3.3 cm"], "answer": 0, "hint": "Work backwards from the eyepiece.", "solution": "Eyepiece object at 5 cm ⇒ objective image at 10 cm ⇒ $\\frac1{10}-\\frac1u=\\frac12$ ⇒ u = −2.5 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q9", "kind": "practice"},
  {"id": "prac-allen26-10", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "An astronomical telescope has angular magnification 5 and tube length 36 cm for the image at infinity. The tube length for the final image at 25 cm is:", "options": ["36.4 cm", "34.8 cm", "30.2 cm", "38 cm"], "answer": 1, "hint": "$f_o=30$, $f_e=6$.", "solution": "Eyepiece object distance $\\frac{150}{31}=4.84$ cm ⇒ 34.84 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q10", "kind": "practice"},
  {"id": "prac-allen26-11", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "A passenger in an aeroplane:", "options": ["never sees a rainbow", "may see primary and secondary rainbows as concentric circles", "may see them as concentric arcs", "never sees a secondary rainbow"], "answer": 1, "hint": "On the ground the horizon cuts the rainbow circle.", "solution": "From above, the whole 42° and 51° cones can be seen: full concentric circles.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q11", "kind": "practice"},
  {"id": "prac-allen26-13", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 1, "q": "The near point of an average person is 25 cm. For an angular magnification of 10 (image at infinity), what is the power of the simple microscope in dioptres?", "answer": 40, "hint": "M = D/f.", "solution": "f = 2.5 cm ⇒ P = 40 D.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q13", "kind": "practice"},
  {"id": "prac-allen26-15", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 3, "q": "Through 8× binoculars you view a 6.28 cm long bird 16 m away. What angle, in degrees, does its image subtend?", "answer": 1.8, "hint": "Find the bird's angle in radians and multiply by 8.", "solution": "6.28/1600 = 3.925×10⁻³ rad = 0.225° ⇒ ×8 = 1.8°.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q15", "kind": "practice"},
  {"id": "prac-allen26-16", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 2, "q": "A 20× telescope has a 12 cm diameter objective. What minimum eyepiece diameter (in cm) collects all rays from an on-axis distant source?", "answer": 0.6, "hint": "The exit beam is narrower by the magnification.", "solution": "12/20 = 0.6 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q16", "kind": "practice"},
  {"id": "prac-allen26-17", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 2, "q": "Ramon's contact lenses are +2.0 D (he is far-sighted). What is his near point without lenses, in cm?", "answer": 50, "hint": "The lens images an object at 25 cm to his near point.", "solution": "$\\frac1v=\\frac1{50}-\\frac1{25}$ ⇒ v = −50 cm ⇒ 50 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q17", "kind": "practice"},
  {"id": "prac-allen26-18", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 3, "q": "A cell structure is 0.61 μm across. Using orange light of 600 nm, what minimum numerical aperture must the objective have to resolve it? (Use $d=\\frac{0.61\\lambda}{NA}$.)", "answer": 0.6, "hint": "Rearrange for NA.", "solution": "$NA=\\frac{0.61\\times0.6}{0.61}=0.6$.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q18", "kind": "practice"},
  {"id": "prac-allen26-19", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 1, "q": "Ellen's glasses are −1.0 D (she is near-sighted). What is her far point without glasses, in cm?", "answer": 100, "hint": "The lens images infinity at her far point.", "solution": "f = −100 cm ⇒ far point 100 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q19", "kind": "practice"},
  {"id": "prac-allen26-20", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "num", "difficulty": 3, "q": "You build a 12× microscope from a 2.0× and a 4.0× magnifier (M = 25 cm/f each), using the 4.0× lens as objective. What tube length (cm) is needed, using $M=\\frac{L}{f_o}\\cdot\\frac{25}{f_e}$?", "answer": 37.5, "hint": "$f_o=6.25$ cm, $f_e=12.5$ cm.", "solution": "$12=\\frac{L}{6.25}\\times2$ ⇒ L = 37.5 cm.", "source": "ALLEN Kota · Assignment 26 (Optical Instruments) · Q20", "kind": "practice"},
  {"id": "prac-jn-ro1-a1", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "Two plane mirrors meet at 60°. A ray reflects off one and then the other. As the angle of incidence θ on the first mirror increases, the angle between the final reflected ray and the incident ray:", "options": ["increases", "decreases", "remains the same", "can't be found without solving each case"], "answer": 2, "hint": "Deviation after two reflections = 360° − 2 × (mirror angle).", "solution": "It stays 240° for any θ.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa1", "kind": "practice"},
  {"id": "prac-jn-ro1-a2", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A ray enters the gap between two mirrors meeting at a small angle α (radians). A reasonable estimate of the maximum number of bounces before it comes back out is:", "options": ["$2\\pi/\\alpha$", "$\\pi/\\alpha$", "$\\sqrt{\\pi/\\alpha}$", "$\\sqrt{\\alpha/\\pi}$"], "answer": 1, "hint": "Each bounce changes the ray's angle with the mirror by α.", "solution": "The angle can change by at most π, so about π/α bounces.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa2", "kind": "practice"},
  {"id": "prac-jn-ro1-a7", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "Reading is more comfortable in bright light than in dim light. The most appropriate reason is:", "options": ["contraction of ciliary muscles reduces astigmatism", "contraction of the pupil in bright light reduces spherical aberration", "the retinal image is more intense", "it is purely psychological"], "answer": 1, "hint": "What changes in the eye in bright light?", "solution": "The pupil narrows, using only paraxial rays and so reducing spherical aberration.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa7", "kind": "practice"},
  {"id": "prac-jn-ro1-a8", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 1, "q": "A car's side-view mirror says \"Objects in mirror are closer than they appear\". Is the image really farther than the object?", "options": ["Yes, smaller and farther", "No, smaller and closer", "No, larger and closer", "Yes, larger and farther"], "answer": 1, "hint": "It's a convex mirror.", "solution": "The virtual image is diminished and lies closer to the mirror than the object; it only looks far because it is small.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa8", "kind": "practice"},
  {"id": "prac-jn-ro1-a9", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A ray parallel to the axis of a concave mirror (radius R) strikes it at angle of incidence θ. After reflection it meets the axis at distance d from the centre of curvature. d is:", "options": ["$\\frac R2$", "$R\\left(1-\\frac1{2\\cos\\theta}\\right)$", "$\\frac{R}{2\\cos\\theta}$", "$\\frac R2(1+\\cos\\theta)$"], "answer": 2, "hint": "The triangle formed with C is isosceles.", "solution": "Angles at C and the axis point are both θ ⇒ $d=\\frac{R}{2\\cos\\theta}$.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa9", "kind": "practice"},
  {"id": "prac-jn-ro1-a12", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A spherical mirror is polished on both sides. Using the convex side, the image is erect with magnification 1/4. Using the concave side with the object at the same distance, the magnification is:", "options": ["−1/4", "−1/2", "−1/3", "+1/4"], "answer": 1, "hint": "Convex: $m=\\frac{F}{F+x}=\\frac14$ ⇒ x = 3F.", "solution": "Concave: $m=\\frac{-F}{-F+3F}=-\\frac12$.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa12", "kind": "practice"},
  {"id": "prac-jn-ro1-a13", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "A parabolic mirror, silvered on its inner surface, has cross-section $y=\\frac{x^2}{4}$ in the xy-plane. A ray travelling along $y=x+3$ hits the mirror in the second quadrant. The direction of the reflected ray is:", "options": ["$\\frac1{\\sqrt2}(-\\hat i-\\hat j)$", "$\\frac1{\\sqrt2}(\\hat i+\\hat j)$", "$\\frac{-2\\hat i-3\\hat j}{\\sqrt{13}}$", "$\\frac{2\\hat i}{\\sqrt3}-\\frac{2\\hat i+\\hat j}{\\sqrt5}$"], "answer": 0, "hint": "Find the hit point, then compare the ray with the normal there.", "solution": "Hit point (−2, 1). Normal ∝ (1, 1), same as the ray ⇒ it retraces: $\\frac{-\\hat i-\\hat j}{\\sqrt2}$.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa13", "kind": "practice"},
  {"id": "prac-jn-ro1-a14", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "Ram sees an erect image with m = 1.8 when a concave mirror is 10 cm from his face. If he holds it 50 cm away:", "options": ["he can't see the image because the rays reaching his eye converge", "he sees a magnified, erect image", "he sees a diminished, inverted image", "he sees a magnified, inverted image"], "answer": 2, "hint": "Find f from the first case.", "solution": "f = −22.5 cm; at 50 cm, image is real at ≈ 41 cm with m ≈ −0.82, between mirror and eye ⇒ diminished, inverted.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qa14", "kind": "practice"},
  {"id": "prac-jn-ro1-b1", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "Plane mirrors AB and AC meet at A at θ = 20°. A ray from P on AC hits AB at Q, then AC at R, then AB at S, and finally ST travels parallel to AC. The angle between the ray and the normal at Q is:", "options": ["20°", "30°", "40°", "60°"], "answer": 1, "hint": "Each reflection between the mirrors changes the ray's grazing angle by θ.", "solution": "Grazing angle with AB at S: 20°; at R with AC: 40°; at Q with AB: 60° ⇒ angle with normal = 30°.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb1", "kind": "practice"},
  {"id": "prac-jn-ro1-b3", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A point object between the pole and focus of a concave mirror moves away from the mirror at constant speed. The image's velocity is:", "options": ["away from the mirror and increasing", "towards the mirror and increasing", "away and decreasing", "towards and decreasing"], "answer": 0, "hint": "The virtual image runs off to infinity as the object nears F.", "solution": "The image moves away (behind the mirror) and speeds up.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb3", "kind": "practice"},
  {"id": "prac-jn-ro1-b4", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A concave mirror lies on a table, axis vertical. A point object at the centre of curvature C gives a real image at C. If the mirror is filled with water, the image will be:", "options": ["real and at C", "real, between C and ∞", "virtual, between C and O", "real, between C and O"], "answer": 3, "hint": "The water raises the system's power (effective focal length f/μ).", "solution": "Object at C is now beyond the new centre of curvature ⇒ real image between C and O.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb4", "kind": "practice"},
  {"id": "prac-jn-ro1-b6", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 5, "q": "A particle is dropped along the axis from height f/2 above a concave mirror of focal length f. The maximum speed of its image is:", "options": ["∞", "$\\frac34\\sqrt{3fg}$", "$\\frac32\\sqrt{3fg}$", "none of these"], "answer": 1, "hint": "Image speed = m² × object speed; maximise over the fall.", "solution": "With y = f − x: $v_i=\\frac{f^2\\sqrt{g(2y-f)}}{y^2}$, maximum at y = 2f/3 ⇒ $\\frac34\\sqrt{3fg}$.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb6", "kind": "practice"},
  {"id": "prac-jn-ro1-b8", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 3, "q": "A reflecting surface is $y=\\frac{2L}{\\pi}\\sin\\frac{\\pi x}{L}$. A ray moving parallel to the x-axis in the first quadrant becomes parallel to the y-axis after reflection. The x-coordinate of the point of incidence is:", "options": ["L/6", "L/3", "L/4", "L/8"], "answer": 1, "hint": "A 90° turn needs a 45° surface.", "solution": "$\\frac{dy}{dx}=2\\cos\\frac{\\pi x}{L}=1$ ⇒ x = L/3.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb8", "kind": "practice"},
  {"id": "prac-jn-ro1-b10", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "An object moves along the axis of a concave mirror (f = −10 cm) towards it at a uniform 5 m/s. When it is at the centre of curvature, the magnitude of the image's acceleration is a m/s². Then a is:", "options": ["10", "5", "25", "none of these"], "answer": 3, "hint": "Differentiate $v_i=-(v/u)^2u'$ once more.", "solution": "At C, v/u = 1 and d(v/u)/dt = 10u′ ⇒ |a| = 2 × 10 × 5 × 5 = 500 m/s²: none of these.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb10", "kind": "practice"},
  {"id": "prac-jn-ro1-b11", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 4, "q": "A convex mirror faces a plane mirror 10 m away. A 1 m tall boy midway between them sees his image in the plane mirror subtend twice the angle of his image in the convex mirror. The focal length of the convex mirror is:", "options": ["5 m", "2.5 m", "1.8 m", "3.6 m"], "answer": 1, "hint": "Plane-mirror image: 1/10 rad. Convex: h′/(5 + v) = 1/20.", "solution": "$\\frac{F}{10F+25}=\\frac1{20}$ ⇒ F = 2.5 m.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb11", "kind": "practice"},
  {"id": "prac-jn-ro1-b12", "exam": "JEE", "subject": "Physics", "chapter": "Ray Optics", "type": "mcq", "difficulty": 2, "q": "A steel spherical mirror has f = 24.0 cm. If its temperature rises by 50 °C ($\\alpha_{steel}=12\\times10^{-5}$/°C), the new focal length is:", "options": ["24.0144 cm", "20.0144 cm", "28.0288 cm", "24.144 cm"], "answer": 3, "hint": "R (and so f) expands linearly.", "solution": "$24(1+12\\times10^{-5}\\times50)=24\\times1.006=24.144$ cm.", "source": "Physics Sir JEE (Janardhan) · Ray Optics Part I · Qb12", "kind": "practice"},
  {"id": "prac-a20-2", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 2, "q": "A racing car moves at a constant 240 km/h around the elliptical track $\\frac{x^2}{16}+\\frac{y^2}{4}=1$ (x, y in km). Find the magnitude of its acceleration (m/s²) at B, the end of the minor axis (0, 2 km).", "answer": 0.556, "tolPct": 2, "hint": "At the end of the minor axis, $\\rho=\\frac{a^2}{b}$.", "solution": "ρ = 16/2 = 8 km; v = 66.67 m/s ⇒ a = v²/ρ = 0.556 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q2", "kind": "practice"},
  {"id": "prac-a20-4", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 4, "q": "A particle starts from O with negligible speed and slides down the curve $y=\\left(\\frac{x}{20}\\right)^2$ ft (y measured downward from O) with speed $v=\\sqrt{2gy}$. Find the normal component of its acceleration (ft/s²) at x = 50 ft. (g = 32.2 ft/s²)", "answer": 1.838, "tolPct": 2, "hint": "$a_n=v^2/\\rho$ with $\\rho=\\frac{(1+y'^2)^{3/2}}{|y''|}$.", "solution": "y = 6.25 ft, v² = 402.5; y′ = 0.25, y″ = 0.005 ⇒ ρ = 219 ft ⇒ aₙ = 1.838 ft/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q4", "kind": "practice"},
  {"id": "prac-a20-5a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 2, "q": "A particle's position is $\\vec r=t^3\\hat i+3t^2\\hat j+8t\\hat k$ m (t in s). At t = 2 s, find the speed (m/s).", "answer": 18.8, "tolPct": 2, "hint": "Differentiate once.", "solution": "v = (12, 12, 8) ⇒ |v| = √352 = 18.8 m/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q5a", "kind": "practice"},
  {"id": "prac-a20-5b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 2, "q": "A particle's position is $\\vec r=t^3\\hat i+3t^2\\hat j+8t\\hat k$ m (t in s). At t = 2 s, find the magnitude of acceleration (m/s²).", "answer": 13.4, "tolPct": 2, "hint": "Differentiate twice.", "solution": "a = (12, 6, 0) ⇒ 13.4 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q5b", "kind": "practice"},
  {"id": "prac-a20-5c", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "A particle's position is $\\vec r=t^3\\hat i+3t^2\\hat j+8t\\hat k$ m (t in s). At t = 2 s, find the radius of curvature of the path (m).", "answer": 51.1, "tolPct": 2, "hint": "$\\rho=\\frac{v^3}{|\\vec v\\times\\vec a|}$.", "solution": "|v×a| = |(−48, 96, −72)| = 129.2 ⇒ ρ = 352^{3/2}/129.2 = 51.1 m.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q5c", "kind": "practice"},
  {"id": "prac-a20-6", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 3, "q": "A toboggan moves down along the parabola $y=0.01x^2$ (m). At A, where x = 60 m, its speed is 10 m/s and increasing at 3 m/s². Find the magnitude of its acceleration (m/s²).", "answer": 3.05, "tolPct": 2, "hint": "Combine tangential 3 m/s² with $v^2/\\rho$.", "solution": "y′ = 1.2, y″ = 0.02 ⇒ ρ = 190.6 m ⇒ aₙ = 0.525 ⇒ a = 3.05 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q6", "kind": "practice"},
  {"id": "prac-a20-7", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 3, "q": "A box slides along the parabola $y=0.4x^2$ (m). At x = 2 m its speed is 8 m/s and increasing at 4 m/s². Find the magnitude of its acceleration (m/s²).", "answer": 8.61, "tolPct": 2, "hint": "Find ρ at x = 2.", "solution": "y′ = 1.6, y″ = 0.8 ⇒ ρ = 8.40 m ⇒ aₙ = 7.62 ⇒ a = √(7.62² + 4²) = 8.61 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q7", "kind": "practice"},
  {"id": "prac-a20-8a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 3, "q": "A particle moves with $r=(t^3+4t-4)$ m and $\\theta=t^{3/2}$ rad (t in s). At t = 2 s, find the magnitude of its velocity (m/s).", "answer": 30.1, "tolPct": 2, "hint": "$v^2=\\dot r^2+(r\\dot\\theta)^2$.", "solution": "r = 12, ṙ = 16, θ̇ = 2.121 ⇒ v = √(256 + 648) = 30.1 m/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q8a", "kind": "practice"},
  {"id": "prac-a20-8b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "A particle moves with $r=(t^3+4t-4)$ m and $\\theta=t^{3/2}$ rad (t in s). At t = 2 s, find the magnitude of its acceleration (m/s²).", "answer": 85.3, "tolPct": 2, "hint": "$a_r=\\ddot r-r\\dot\\theta^2$, $a_\\theta=r\\ddot\\theta+2\\dot r\\dot\\theta$.", "solution": "r̈ = 12, θ̈ = 0.530 ⇒ a_r = −42, a_θ = 74.2 ⇒ a = 85.3 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q8b", "kind": "practice"},
  {"id": "prac-a20-10a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "A car moves along $r=\\frac{200}{\\theta}$ ft (θ in rad) at a constant speed of 35 ft/s. At θ = π/3, find the radial component of velocity (ft/s).", "answer": -24.2, "tolPct": 2, "hint": "$\\dot r=-\\frac{200}{\\theta^2}\\dot\\theta$, $r\\dot\\theta=\\frac{200}{\\theta}\\dot\\theta$; use the speed to get θ̇.", "solution": "θ̇ = 0.1325 rad/s ⇒ v_r = −24.2 ft/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q10a", "kind": "practice"},
  {"id": "prac-a20-10b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "A car moves along $r=\\frac{200}{\\theta}$ ft (θ in rad) at a constant speed of 35 ft/s. At θ = π/3, find the transverse component of velocity (ft/s).", "answer": 25.3, "tolPct": 2, "hint": "Same θ̇ as the radial part.", "solution": "v_θ = (200/θ)θ̇ = 25.3 ft/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q10b", "kind": "practice"},
  {"id": "prac-a20-12a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 3, "q": "Sphere P moves in a straight line at 10 m/s, as shown (P is 5 m right of and 4 m above O; its velocity points down-left at 30° to the vertical). At this instant, find $\\dot r$ (m/s).", "img": "figures/prac-a20-q12.png", "imgAlt": "P at (5 m, 4 m) from O, velocity 10 m/s directed down-left at 30° to the vertical", "answer": -9.31, "tolPct": 2, "hint": "$\\dot r=\\vec v\\cdot\\hat r$.", "solution": "v = (−5, −8.66), r̂ = (5, 4)/√41 ⇒ ṙ = −9.31 m/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q12a", "kind": "practice"},
  {"id": "prac-a20-12b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 3, "q": "Sphere P moves in a straight line at 10 m/s, as shown (P is 5 m right of and 4 m above O; its velocity points down-left at 30° to the vertical). At this instant, find $\\dot\\theta$ (rad/s).", "img": "figures/prac-a20-q12.png", "imgAlt": "P at (5 m, 4 m) from O, velocity 10 m/s directed down-left at 30° to the vertical", "answer": -0.568, "tolPct": 2, "hint": "$\\dot\\theta=\\frac{xv_y-yv_x}{r^2}$.", "solution": "(−43.3 + 20)/41 = −0.568 rad/s.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q12b", "kind": "practice"},
  {"id": "prac-a20-13a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "Sphere P moves in a straight line at 10 m/s, as shown (P is 5 m right of and 4 m above O; its velocity points down-left at 30° to the vertical). At this instant, the speed is constant. Find $\\ddot r$ (m/s²).", "img": "figures/prac-a20-q12.png", "imgAlt": "P at (5 m, 4 m) from O, velocity 10 m/s directed down-left at 30° to the vertical", "answer": 2.07, "tolPct": 2, "hint": "No acceleration ⇒ $\\ddot r-r\\dot\\theta^2=0$.", "solution": "r̈ = 6.403 × 0.568² = 2.07 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q13a", "kind": "practice"},
  {"id": "prac-a20-13b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 4, "q": "Sphere P moves in a straight line at 10 m/s, as shown (P is 5 m right of and 4 m above O; its velocity points down-left at 30° to the vertical). At this instant, the speed is constant. Find $\\ddot\\theta$ (rad/s²).", "img": "figures/prac-a20-q12.png", "imgAlt": "P at (5 m, 4 m) from O, velocity 10 m/s directed down-left at 30° to the vertical", "answer": -1.653, "tolPct": 2, "hint": "$r\\ddot\\theta+2\\dot r\\dot\\theta=0$.", "solution": "θ̈ = −2(−9.31)(−0.568)/6.403 = −1.653 rad/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q13b", "kind": "practice"},
  {"id": "prac-a20-14a", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 3, "q": "A jet flies at constant speed at altitude h = 10 km and is tracked by a radar directly below its line of flight. At θ = 60° (angle of the line of sight above the horizontal), θ is decreasing at 0.020 rad/s. Find $\\ddot r$ (m/s²).", "answer": 4.62, "tolPct": 2, "hint": "Constant velocity ⇒ $\\ddot r=r\\dot\\theta^2$.", "solution": "r = h/sin 60° = 11547 m ⇒ r̈ = 11547 × 0.0004 = 4.62 m/s².", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q14a", "kind": "practice"},
  {"id": "prac-a20-14b", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 2, "q": "A jet flies at constant speed at altitude h = 10 km and is tracked by a radar directly below its line of flight. At θ = 60° (angle of the line of sight above the horizontal), θ is decreasing at 0.020 rad/s. Find the plane's speed (km/h).", "answer": 960, "hint": "$x=h\\cot\\theta$ ⇒ $\\dot x=-h\\csc^2\\theta\\,\\dot\\theta$.", "solution": "v = 10⁴ × (4/3) × 0.02 = 266.7 m/s = 960 km/h.", "source": "ALLEN Kota · Nurture Assignment 20 (Circular Motion) · Q14b", "kind": "practice"},
  {"id": "prac-a21-1", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 2, "q": "A particle moves with constant speed v along $y=kx^2$ (k > 0). The magnitude of its acceleration at x = 0 is:", "options": ["$2kv^2$", "$kv^2$", "$\\frac{kv^2}{2}$", "$\\frac{kv^2}{4}$"], "answer": 0, "hint": "Curvature at the vertex = |y″|.", "solution": "ρ = 1/(2k) ⇒ a = v²/ρ = 2kv².", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q1", "kind": "practice"},
  {"id": "prac-a21-2", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 3, "q": "A bead slides without friction on a fixed parabolic wire $x^2=4ay$ (axis vertical, vertex at the origin). Released from rest at y = 4a, its tangential acceleration at y = a is:", "options": ["g/2", "$\\frac{\\sqrt3g}{2}$", "$\\frac{g}{\\sqrt2}$", "$\\frac{g}{\\sqrt5}$"], "answer": 2, "hint": "$a_t=g\\sin\\phi$, where tan φ is the slope.", "solution": "At y = a, x = 2a ⇒ slope x/2a = 1 ⇒ φ = 45° ⇒ g/√2.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q2", "kind": "practice"},
  {"id": "prac-a21-3", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 2, "q": "A particle has velocity $(4\\hat i+4\\hat j)$ m/s and acceleration $(3\\hat i+5\\hat j)$ m/s². The radius of curvature of its path at that instant is:", "options": ["$16\\sqrt2$ m", "15 m", "18 m", "none of these"], "answer": 0, "hint": "$\\rho=\\frac{v^3}{|\\vec v\\times\\vec a|}$.", "solution": "v³ = 32√32 = 128√2, |v×a| = 8 ⇒ ρ = 16√2 m.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q3", "kind": "practice"},
  {"id": "prac-a21-5", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 4, "q": "A rope of length l = na (n an integer) is tied to a fixed beam of square cross-section (edge a) on a smooth floor. The mass at its end is given speed v perpendicular to the rope. How long does the rope take to wind completely round the beam?", "options": ["$\\frac{\\pi n(n+1)a}{4v}$", "$\\frac{\\pi n(n+1)a}{2v}$", "$\\frac{\\pi n^2(n+1)a}{2v}$", "$\\frac{\\pi n^2(n+1)a}{4v}$"], "answer": 0, "hint": "Speed stays v; each quarter turn the free length shrinks by a.", "solution": "$t=\\sum_{k=0}^{n-1}\\frac{\\pi}{2}\\frac{(n-k)a}{v}=\\frac{\\pi a}{2v}\\cdot\\frac{n(n+1)}{2}$.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q5", "kind": "practice"},
  {"id": "prac-a21-7", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 1, "q": "The Moon does not fall to Earth because:", "options": ["the net force on it is zero", "it is beyond Earth's pull", "it is pulled by the Sun and planets as well", "the statement is wrong: the Moon is in free fall"], "answer": 3, "hint": "What does gravity do to an orbiting body?", "solution": "It continuously falls towards Earth, but its sideways speed keeps it in orbit.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q7", "kind": "practice"},
  {"id": "prac-a21-9", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 3, "q": "A particle moves as $\\vec r=a\\cos\\omega t\\,\\hat i+a\\sin\\omega t\\,\\hat j+bt\\,\\hat k$ with $\\omega=2\\pi/T$. The distance moved in one full turn of the helix is:", "options": ["$\\frac{4\\pi}{\\omega}\\sqrt{a^2+b^2\\omega^2}$", "$\\frac{2\\pi}{\\omega}\\sqrt{a^2\\omega^2+b^2}$", "$\\frac{2\\pi}{\\omega}\\sqrt{a^2+b^2\\omega^2}$", "$\\frac{4\\pi}{\\omega}\\sqrt{a^2\\omega^2+b^2}$"], "answer": 1, "hint": "Speed is constant.", "solution": "$v=\\sqrt{a^2\\omega^2+b^2}$ for time $2\\pi/\\omega$.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q9", "kind": "practice"},
  {"id": "prac-a21-10", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 3, "q": "A particle moves at constant speed v along $y=k\\sin(x/L)$ (k, L > 0). When y = k, the magnitude of its acceleration is:", "options": ["$\\frac{kv^2}{2L^2}$", "zero", "$\\frac{kv^2}{L^2}$", "none"], "answer": 2, "hint": "At the crest the slope is zero.", "solution": "Curvature = |y″| = k/L² ⇒ a = kv²/L².", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q10", "kind": "practice"},
  {"id": "prac-a21-11", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 4, "q": "A particle moves at constant speed v along $y=k\\sin(x/L)$, entering the first quadrant from the origin. The value of $v_x$ when y = k/2 is:", "options": ["$\\frac{2vL}{\\sqrt{2L^2+3k^2}}$", "$\\frac{2vL}{\\sqrt{4L^2+3k^2}}$", "$\\frac{2kv}{\\sqrt{k^2+3L^2}}$", "none"], "answer": 1, "hint": "$v_x=\\frac{v}{\\sqrt{1+y'^2}}$.", "solution": "sin = ½ ⇒ y′ = (k/L)(√3/2) ⇒ $v_x=\\frac{2vL}{\\sqrt{4L^2+3k^2}}$.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q11", "kind": "practice"},
  {"id": "prac-a21-15", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "The Coriolis force on a body moving with velocity $\\vec v$ relative to the rotating Earth is $-2m\\vec\\omega\\times\\vec v$, where $\\vec\\omega$ is Earth's angular velocity (pointing from the South to the North Pole). If a body is projected northward in the southern hemisphere, the Coriolis force on it is towards the:", "options": ["east", "west", "up", "it is zero"], "answer": 1, "hint": "In the south, the horizontal deflection is to the left of the motion.", "solution": "Moving north with left-hand deflection ⇒ west.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q15", "kind": "practice"},
  {"id": "prac-a21-16", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "The Coriolis force on a body moving with velocity $\\vec v$ relative to the rotating Earth is $-2m\\vec\\omega\\times\\vec v$, where $\\vec\\omega$ is Earth's angular velocity (pointing from the South to the North Pole). The work done by the Coriolis force on the body is:", "options": ["positive", "negative", "zero", "positive, then negative"], "answer": 2, "hint": "The force is perpendicular to the velocity.", "solution": "F ⊥ v ⇒ zero work.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q16", "kind": "practice"},
  {"id": "prac-a21-17", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "The Coriolis force on a body moving with velocity $\\vec v$ relative to the rotating Earth is $-2m\\vec\\omega\\times\\vec v$, where $\\vec\\omega$ is Earth's angular velocity (pointing from the South to the North Pole). In what direction should a body be projected from the equator so that the Coriolis force on it is zero?", "options": ["North", "East", "Up", "It is zero in every direction"], "answer": 0, "hint": "$\\vec\\omega\\times\\vec v=0$ needs v ∥ ω.", "solution": "At the equator, ω points north ⇒ project northward.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q17", "kind": "practice"},
  {"id": "prac-a21-18", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 3, "q": "In a projectile's hodograph (velocity vectors drawn from one origin), the triangle formed by $\\vec v_0$, $\\vec v$ and $\\vec gt$ has area equal to:", "options": ["½ g × vertical displacement", "½ g × horizontal displacement", "distance travelled × g", "g × displacement"], "answer": 1, "hint": "Base gt, height = horizontal velocity component.", "solution": "Area = ½ (gt)(v₀cosθ) = ½ g × (v₀cosθ·t).", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q18", "kind": "practice"},
  {"id": "prac-a21-21", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 3, "q": "An 80 kg athlete runs at a constant 5 m/s along a rough track: a cylindrical valley AB (radius 100 m, A its lowest point) joins smoothly to a cylindrical hill BC (radius 200 m, C its top). From A to C the athlete covers 150 m horizontally. (g = 10 m/s²) The time taken from A to C is:", "options": ["5π s", "10π s", "15π s", "20π s"], "answer": 1, "hint": "Both arcs turn through the same angle θ: 100 sinθ + 200 sinθ = 150.", "solution": "θ = 30° ⇒ path = (100 + 200)(π/6) = 50π m ⇒ 10π s.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q21", "kind": "practice"},
  {"id": "prac-a21-22", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 3, "q": "An 80 kg athlete runs at a constant 5 m/s along a rough track: a cylindrical valley AB (radius 100 m, A its lowest point) joins smoothly to a cylindrical hill BC (radius 200 m, C its top). From A to C the athlete covers 150 m horizontally. (g = 10 m/s²) The correct order of the normal forces is:", "options": ["$N_A>N_B>N_C$", "$N_A<N_B<N_C$", "$N_A>N_C>N_B$", "$N_C>N_A>N_B$"], "answer": 2, "hint": "Valley adds $mv^2/r$; hill subtracts it; B also has slope 30°.", "solution": "N_A = 820 N, N_C = 790 N, N_B ≈ 683–713 N.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q22", "kind": "practice"},
  {"id": "prac-a21-23", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 3, "q": "An 80 kg athlete runs at a constant 5 m/s along a rough track: a cylindrical valley AB (radius 100 m, A its lowest point) joins smoothly to a cylindrical hill BC (radius 200 m, C its top). From A to C the athlete covers 150 m horizontally. (g = 10 m/s²) The friction force on the athlete:", "options": ["is zero throughout", "decreases continuously", "increases continuously", "is maximum at B"], "answer": 3, "hint": "At constant speed, friction balances $mg\\sin(\\text{slope})$.", "solution": "The slope is steepest (30°) at B.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q23", "kind": "practice"},
  {"id": "prac-a21-25", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "mcq", "difficulty": 2, "q": "A plane flies from Vladivostok to Moscow (9000 km apart on the same latitude) in 9 hours, keeping pace with the Sun. With Earth's equatorial circumference 40,000 km, the latitude is:", "options": ["37°", "53°", "45°", "insufficient information"], "answer": 1, "hint": "The parallel's circumference is covered in 24 h at 1000 km/h.", "solution": "24,000 = 40,000 cos φ ⇒ φ = 53°.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q25", "kind": "practice"},
  {"id": "prac-a21-27", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 4, "q": "A toy car moves anticlockwise on the track shown (straight parts 2 m, semicircles of radius 1 m); the graph gives its speed vs distance from P. One lap takes 6k seconds. Find k. (Take π ln 2 ≈ 2)", "img": "figures/prac-a21-q27.png", "imgAlt": "Race track with 2 m straights and 1 m radius ends; speed–distance graph dropping from 0.25 to 0.125 m/s mid-curve", "answer": 8, "hint": "On straights t = s/v; where v varies linearly with s, $t=\\int ds/v$.", "solution": "Straights: 2×8 = 16 s. Each quarter-arc: (π/2)/0.125 × ln 2 = 4π ln 2 = 8 s; four of them: 32 s. Total 48 = 6k ⇒ k = 8.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q27", "kind": "practice"},
  {"id": "prac-a21-28", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "num", "difficulty": 2, "q": "Particle A at (0, 2 m) has velocity $5\\hat i$ m/s and B at (2 m, 0) has $13\\hat j$ m/s. Find the magnitude of the angular velocity of A relative to B (rad/s).", "answer": 2, "hint": "$\\omega=\\frac{|\\vec r_{AB}\\times\\vec v_{AB}|}{r^2}$.", "solution": "r = (−2, 2), v = (5, −13) ⇒ (26 − 10)/8 = 2 rad/s.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q28", "kind": "practice"},
  {"id": "prac-a21-29", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 4, "q": "Beads m and 2m, joined by a massless rod of length R, are threaded on a smooth circular wire of radius R that rotates at ω about a vertical diameter. The beads don't slide and the rod stays vertical as shown. Find ω (rad/s). (R = 15 m, g = 10 m/s²)", "img": "figures/prac-a21-q29.png", "imgAlt": "Circular wire rotating about a vertical diameter; a vertical rod of length R joins bead m (top) and 2m (bottom) on the wire", "answer": 2, "hint": "The wire's normal forces point to its centre; balance horizontal forces for each bead.", "solution": "N₁ = mω²R, N₂ = 2mω²R; vertical balance of both: ½(N₂ − N₁) = 3mg ⇒ ω² = 6g/R = 4 ⇒ 2 rad/s.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q29", "kind": "practice"},
  {"id": "prac-a21-30", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 4, "q": "A particle passes O at 12 m/s and slows to 5 m/s at A, 18 m further along the curve. Its tangential deceleration is proportional to its distance from O. If its total acceleration at A is 10 m/s², find the radius of curvature at A (m).", "answer": 3.33, "tolPct": 2, "hint": "$v^2=144-ks^2$.", "solution": "k = 119/324 ⇒ a_t = 6.61 ⇒ aₙ = 7.50 ⇒ ρ = 25/7.50 = 3.33 m.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q30", "kind": "practice"},
  {"id": "prac-a21-31", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 3, "q": "In a train that starts from rest, a load hanging from a spring balance tilts backward for the first 4 s and the balance reads 5mg/4. Later, on a circular track at the speed reached, the load tilts sideways and the reading is again 5mg/4. Find the radius of the track (m). (g = 10 m/s²)", "answer": 120, "hint": "Reading 5mg/4 ⇒ horizontal acceleration 3g/4.", "solution": "v = 7.5 × 4 = 30 m/s ⇒ R = v²/(3g/4) = 120 m.", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q31", "kind": "practice"},
  {"id": "prac-a21-33", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 3, "q": "An object in uniform circular motion has speed 4 m/s. The change in its velocity over 0.5 s has magnitude 4 m/s. Find the minimum possible centripetal acceleration (m/s²). (π = 25/8)", "answer": 8.33, "tolPct": 2, "hint": "|Δv| = 2v sin(Δθ/2).", "solution": "Δθ = π/3 in 0.5 s ⇒ ω = 2π/3 ⇒ a = vω = 8π/3 = 8.33 m/s².", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q33", "kind": "practice"},
  {"id": "prac-a21-35", "exam": "JEE", "subject": "Physics", "chapter": "Circular Motion", "type": "num", "difficulty": 3, "q": "A stone whirls in a horizontal circle 2 m above the ground on a 1.5 m string (circle radius 1.5 m). The string breaks and the stone lands 10 m away horizontally. Find its centripetal acceleration (m/s²). (g = 10 m/s²)", "answer": 166.67, "tolPct": 2, "hint": "Fall time from 2 m.", "solution": "t = √0.4 ⇒ v² = 100/0.4 = 250 ⇒ a = 250/1.5 = 166.7 m/s².", "source": "ALLEN Kota · Nurture Assignment 21 (Circular Motion) · Q35", "kind": "practice"}
);
